window.__detail("2026-11-04",[{"id":"2026-11-04-1","date":"2026-11-04","tag":"감독·계리","title":"올해 결산부터 '계리가정 근거'를 보고서로, 보험업감독규정이 바뀌었다","predict":{"q":"보험사가 계리가정의 근거와 검증 결과를 담은 보고서를 금감원에 내야 하는 건 언제부터일까요?","options":["2027회계연도 결산분부터","2026회계연도 결산분부터","2028회계연도 결산분부터"],"answer":1,"reveal":"**2026회계연도 결산분부터** 매년 사업보고서 제출 기한에 맞춰 내야 해요. 금융위원회는 11월 4일 이 내용을 담은 보험업감독규정 개정안을 의결했어요. 연중에 계리가정을 바꾸면 **위험관리위원회에 보고**하는 의무도 생겼어요."},"comic":{"title":"가정에도 근거가 필요해","panels":[{"caption":"금융위원회 의결 날","bg":"meeting","chars":[{"who":"regulator","mood":"thinking","pose":"doc","say":"가정의 근거를 보고서로 내세요"},{"who":"insurer","mood":"surprised","fx":"exclaim"}]},{"caption":"가정을 바꿀 때도","bg":"office","chars":[{"who":"insurer","mood":"worried","pose":"worry","say":"중간에 바꿔도 보고해요?"},{"who":"regulator","mood":"happy","pose":"point","say":"위험관리위원회에요"}]},{"caption":"금리 위험도 새로 재요","bg":"focus","sign":"듀레이션 갭","chars":[{"who":"mango","mood":"thinking","pose":"think","say":"자산과 부채의 금리 민감도 차이!"}]},{"caption":"망고 계리사의 정리","bg":"office","board":"up","chars":[{"who":"mango","mood":"happy","pose":"point","fx":"idea","say":"가정의 근거가 곧 실력이에요"}]}]},"numbers":[{"label":"계리가정보고서 제출","value":"2026회계연도","note":"결산분부터 매년"},{"label":"내부통제·대리점 평가 시행","value":"2027.1.1","note":"재무제표 작성기준도 함께"},{"label":"듀레이션 갭 지표","value":"2028.1.1","note":"경영실태평가 금리위험 계량지표"},{"label":"1·2세대 실손 전환 할인","value":"3년 50%","note":"11월 중 시행"}],"points":["보험사는 책임준비금과 지급여력기준금액을 계산할 때 쓴 **계리가정의 산출 근거와 방법, 주요 변경 사항, 검증 결과**를 담고 현금흐름 모델링과 내부통제 내용까지 넣은 계리가정보고서를 매년 금감원에 내야 해요. 당국은 회사별·상품별 가정 수준과 변화를 비교해 이상 징후를 일찍 찾겠다고 했어요.","계리가정 내부통제기준을 꼭 만들어야 하고, 연중에 가정을 바꾸면 사유·내용·재무 영향을 위험관리위원회에 보고해야 해요. 경영실태평가에는 금리위험 지표로 **듀레이션 갭**이, 경영관리 부문에는 **법인보험대리점 운영위험 관리**가 새 평가 항목으로 들어가요.","1·2세대 실손 가입자가 5세대로 갈아탈 때의 계약전환 할인 상품은 단독형이 아니라 기존 주계약에 특약으로 붙일 수 있게 했어요. 비상위험준비금은 그해 적립대상 보험료를 기준으로 쌓도록 하고, 내년 새 회계기준에 맞춰 손익계산서 항목도 정비해요."],"why":"새 회계기준에서는 계리가정 하나로 보험부채와 이익이 크게 달라져요. 그래서 당국은 숫자만 보는 게 아니라 **'그 숫자를 왜 그렇게 정했는지'를 매년 문서로 확인**하겠다는 거예요. 계리 직무에서는 가정을 정하는 것만큼 근거를 설명하고 검증하는 일이 중요해지고, 리스크관리 직무에서는 자산과 부채의 금리 민감도를 맞추는 능력이 평가받게 돼요. 이런 뉴스를 볼 땐 \"이 규정이 계리팀의 1년 일정을 어떻게 바꿀까\"를 떠올려보세요.","chain":["계리가정에 따라 보험부채와 이익이 크게 달라짐","보험부채 평가의 신뢰성을 높일 필요가 커짐","계리가정보고서 매년 제출과 내부통제 의무화","당국이 회사·상품별 가정을 비교해 이상 징후를 찾음","가정의 근거와 검증 과정이 더 중요해짐","계리·리스크관리 직무의 책임과 역할이 커짐"],"role":{"q":"당신은 손해보험사 계리팀 신입이에요. 팀장님이 말합니다. \"올해 결산부터 계리가정보고서를 내야 해. 해지율 가정 부분에는 뭘 담아야 할까?\" 목차를 짜보세요.","model":"첫째, **산출 근거**예요. 어떤 기간의 경험 통계를 썼는지, 상품군과 경과기간을 어떻게 나눴는지 적어요. 둘째, **산출 방법**이에요. 경험 통계를 그대로 썼는지, 업계 통계나 전망을 섞었는지와 그 이유를 밝혀요. 셋째, **작년과 달라진 점**과 그 이유, 그리고 그 변경이 보험계약마진과 이익에 준 영향을 숫자로 보여줘요. 넷째, **검증 결과**예요. 실제 해지와 가정의 차이(예실차)를 비교해 가정이 맞았는지 확인한 내용을 넣어요. 마지막으로 가정 변경을 누가 검토하고 승인했는지, 연중 변경 때 위험관리위원회에 어떻게 보고했는지 같은 **내부통제 절차**를 정리해요."},"summary":"보험사가 보험료랑 부채 계산할 때 쓰는 예상치를 왜 그렇게 잡았는지 매년 보고서로 내야 하고, 중간에 바꾸면 이사회 위원회에도 보고해야 해.","interview":{"q":"계리가정보고서 제출 의무화가 계리 직무에 어떤 변화를 가져올지 말해보세요.","guide":"결론부터: 가정을 정하는 일에서 그 근거를 설명하고 검증하는 일까지 계리 직무의 책임이 넓어진다고 말해요.\n근거: 금융위는 11월 4일 개정안을 의결해 2026회계연도 결산분부터 계리가정보고서 제출, 계리가정 내부통제, 연중 변경 시 위험관리위원회 보고를 의무화했어요.\n관점: 계리 관점에서 예실차 분석과 현금흐름 모델의 투명성이 핵심 역량이 된다고 덧붙여요.\n마무리: 근거가 분명한 가정으로 회사와 당국 모두가 믿을 수 있는 숫자를 만들고 싶다고 마무리해요."},"quiz":[{"q":"계리가정보고서에 담기는 내용이 아닌 것은?","o":["다음 해 신계약 판매 목표와 영업 계획","가정의 산출 근거와 방법","검증 결과와 현금흐름 모델링"],"a":0,"e":"보고서에는 산출 근거·방법, 주요 변경 사항, 검증 결과, 현금흐름 모델링, 내부통제 내용이 담겨요."},{"q":"연중에 계리가정을 바꾸면 어디에 보고해야 할까?","o":["감사위원회","위험관리위원회","보험개발원"],"a":1,"e":"사유·내용·재무 영향을 이사회 안의 위험관리위원회에 보고해야 해요. 법령 개정 때문이거나 영향이 미미하면 빼요."},{"q":"듀레이션 갭이 크다는 것은 무엇을 뜻할까?","o":["해지가 늘 때 보험계약마진이 크게 줄어들 수 있다","보험금 청구가 늘 때 손해율이 크게 오를 수 있다","금리가 움직일 때 순자산 가치가 크게 흔들릴 수 있다"],"a":2,"deep":true,"e":"자산과 부채의 금리 민감도 차이가 크면, 금리 변화에 자산과 부채가 다르게 움직여 순자산 가치가 크게 변해요."}],"terms":[{"t":"계리가정보고서","d":"보험사가 계리가정의 체계, 산출 근거와 결과, 내부통제를 담아 금감원에 내는 보고서예요."},{"t":"계리가정","d":"보험료와 보험부채를 계산할 때 쓰는 예상 손해율, 해지율, 사업비율 같은 전제예요."},{"t":"듀레이션 갭","d":"자산과 부채의 듀레이션 차이예요. 클수록 금리가 움직일 때 순자산 가치가 크게 흔들려요."},{"t":"경영실태평가","d":"금융당국이 보험사의 경영 상태를 자본, 위험, 경영관리 같은 부문별로 평가하는 제도예요."},{"t":"비상위험준비금","d":"큰 재해처럼 드물지만 큰 손실에 대비해 보험료의 일부를 따로 쌓아두는 준비금이에요."},{"t":"법인보험대리점","d":"특정 보험사에 소속되지 않고 여러 보험사 상품을 함께 파는 판매 회사예요."}],"thread":{"id":"actuarial-supervision","name":"계리감독 강화"},"jobs":["계리","리스크관리"],"figs":[{"type":"timeline","title":"바뀐 감독규정, 언제부터 적용될까","items":[{"when":"2026년 11월 4일","label":"금융위원회 개정안 의결","now":true},{"when":"2026년 11월 중","label":"1·2세대 실손 계약전환 할인과 선택형 특약 할인 시행"},{"when":"2026회계연도 결산","label":"계리가정보고서 첫 제출"},{"when":"2027년 1월 1일","label":"계리가정 내부통제, 대리점 운영위험 평가, 재무제표 작성기준 적용"},{"when":"2028년 1월 1일","label":"경영실태평가 듀레이션 갭 지표 시행"}],"look":"의결 뒤 2026회계연도 결산, 2027년, 2028년 순으로 적용돼요."}],"sources":[{"name":"아시아투데이","url":"https://www.asiatoday.co.kr/kn/view.php?key=20261104010001788"},{"name":"데일리안","url":"https://www.dailian.co.kr/news/view/1710884/%EB%B3%B4%ED%97%98%EC%82%AC-%EA%B3%84%EB%A6%AC%EA%B0%80%EC%A0%95-%EA%B4%80%EB%A6%AC-%EA%B0%95%ED%99%94GA-%ED%8C%90%EB%A7%A4%EC%9C%84-2026"}],"brief":{"what":"금융위원회가 11월 4일 보험업감독규정 개정안을 의결해, 보험사가 **2026회계연도 결산분부터** 계리가정보고서를 매년 금감원에 내야 해요.","why":"계리가정 하나로 보험부채와 이익이 크게 달라지니, 당국이 숫자만 보지 않고 그 숫자를 왜 그렇게 정했는지 문서로 확인하려는 거예요.","so":"계리팀은 가정의 근거를 설명하고 검증하는 일이 커지고, 연중에 가정을 바꾸면 위험관리위원회에 보고해야 해요."},"pre":["계리가정","계리가정보고서"]},{"id":"2026-11-04-2","date":"2026-11-04","tag":"정보보호","title":"보험권 첫 해킹, 미래에셋생명 점검이 길어지는 이유","predict":{"q":"금감원의 미래에셋생명 현장점검이 예정(10월 30일)보다 길어진 가장 큰 이유는?","options":["손해배상안 협의가 길어져서","유출 원인이 직원의 실수로 바뀌어서","유출 범위가 처음 파악보다 넓어져서"],"answer":2,"reveal":"처음 공지 뒤 **퇴직연금 거래 정보와 2차 유출 정보**가 더 확인되면서 범위가 넓어졌어요. 금감원은 성급히 결론을 냈다가 추가 피해가 드러나는 일을 막으려고 **피해 규모 확정에 신중**한 태도예요."},"numbers":[{"label":"현장점검 예정 종료일","value":"10월 30일","note":"1차례 연장, 종료일 미통지"},{"label":"1차 유출 공지","value":"10월 28일","note":"이름·주민등록번호·계좌번호 등"},{"label":"참고 사례: 국민은행 추가 확인","value":"2,091명","note":"처음 119명 발표 24일 뒤"}],"points":["미래에셋생명은 보험사 가운데 처음으로 해킹 사고가 확인된 곳이에요. 처음에는 이름, 주민등록번호, 휴대전화번호, 이메일, 주소, 연계정보, 계좌번호 유출을 알렸고, 이후 **퇴직연금 거래 정보**와 운전면허증 사본, 통장 사본, 퇴직소득 원천징수영수증 같은 2차 유출 정보도 확인됐어요.","이찬진 금감원장은 3일 임원회의에서 증권사·보험사 개인정보 유출에 대한 **최고경영자 책임**을 언급했어요. 금감원은 기술 점검뿐 아니라 내부통제와 대응 절차까지 살피고, 법 위반이 보이면 정식 검사로 바꿀 수도 있어요.","피해 대상과 규모를 확정한 뒤에 손해배상안을 만들 계획이라 **보상안은 당장 나오기 어려워요**. 회사는 지금 개인정보보호법에 따른 손해배상과 법정손해배상 청구가 가능하다고만 안내하고 있어요."],"why":"보험사는 주민등록번호, 계좌, 건강 정보, 퇴직연금 거래까지 **가장 민감한 정보를 오래 보관하는 회사**예요. 해킹 한 번이 배상 비용, 제재, 고객 이탈, 신뢰 하락으로 이어질 수 있어요. 리스크관리 관점에서 정보보호는 이제 전산 부서만의 일이 아니라 경영진이 책임지는 운영위험이에요. 이런 뉴스를 볼 땐 \"사고 하나가 어떤 비용들로 번져가는지\"를 줄줄이 적어보세요.","chain":["해킹으로 고객 개인정보가 유출됨","퇴직연금 거래 정보 등 유출 범위가 넓어짐","금감원 현장점검이 연장됨","피해 대상과 규모 확정이 늦어짐","손해배상안 마련도 늦어짐","내부통제와 경영진 책임까지 점검 대상이 됨"],"role":{"q":"당신은 보험사 리스크관리팀 신입이에요. 팀장님이 묻습니다. \"다른 보험사 해킹 사고에서 우리가 배울 점이 뭘까?\" 세 가지로 정리해보세요.","model":"첫째, **유출 범위를 빨리 정확히 파악하는 체계**가 필요해요. 미래에셋생명처럼 처음 발표 뒤 범위가 넓어지면 점검이 길어지고 신뢰가 더 떨어져요. 둘째, 보험사는 계좌, 신분증 사본, 퇴직연금 정보처럼 민감한 서류를 많이 가지고 있으니 **꼭 필요한 정보만, 필요한 기간만 보관**하는 원칙을 다시 점검해야 해요. 셋째, 금감원장이 최고경영자 책임을 언급한 만큼 정보보호를 **운영위험으로 보고 이사회에 정기 보고**하고, 배상 비용 같은 손실 규모를 미리 추정해 대비하는 게 좋아요."},"summary":"미래에셋생명이 해킹당했는데 털린 정보가 계속 더 나와서, 금감원 점검도 길어지고 보상안도 아직 못 나오고 있어.","interview":{"q":"보험사의 개인정보 유출 사고가 회사에 어떤 위험을 주는지 설명해보세요.","guide":"결론부터: 배상과 제재 같은 직접 비용뿐 아니라 신뢰 하락과 고객 이탈이라는 큰 운영위험이 된다고 말해요.\n근거: 미래에셋생명은 보험권 첫 해킹 사례로, 퇴직연금 거래 정보까지 유출 범위가 넓어져 금감원 점검이 연장됐고, 금감원장은 최고경영자 책임을 언급했어요.\n관점: 리스크관리 관점에서 정보보호를 경영진이 관리하는 운영위험으로 다루고, 손실 규모를 미리 추정해야 한다고 덧붙여요.\n마무리: 보험은 믿음을 파는 업이라 정보보호가 곧 상품의 일부라고 마무리해요."},"quiz":[{"q":"미래에셋생명 사고가 업계에서 주목받는 이유는?","o":["금감원이 처음으로 최고경영자를 제재한 사고라서","유출된 정보에 건강 정보가 처음 포함된 사고라서","보험사 가운데 처음 확인된 해킹 사고라서"],"a":2,"e":"보험사 중 처음으로 해킹 사고가 확인된 사례예요."},{"q":"금감원이 이번 점검에서 기술 점검 말고 함께 살피겠다고 한 것은?","o":["상품 판매 절차와 설명 의무","내부통제와 대응 절차","재보험 출재 구조"],"a":1,"e":"최고경영자 책임까지 언급하며 내부통제 체계와 대응 절차를 포괄적으로 보겠다고 했어요."},{"q":"리스크관리 관점에서 개인정보 유출은 어떤 위험으로 분류하는 게 가장 알맞을까?","o":["금리위험","보험위험","운영위험"],"a":2,"deep":true,"e":"사람, 시스템, 내부 절차의 실패에서 생기는 손실이라 운영위험으로 봐요."}],"terms":[{"t":"현장점검","d":"금융당국이 회사에 직접 나가 특정 문제를 확인하는 일이에요. 문제가 크면 정식 검사로 바뀌기도 해요."},{"t":"법정손해배상","d":"피해자가 실제 손해액을 증명하지 않아도 법이 정한 범위에서 배상을 청구할 수 있는 제도예요."},{"t":"운영위험","d":"사람, 시스템, 내부 절차의 잘못이나 외부 사건 때문에 생기는 손실 위험이에요."},{"t":"내부통제","d":"회사가 직원과 판매조직의 잘못된 행동을 미리 막고 점검하는 관리 체계예요."}],"thread":{"id":"insurer-security","name":"보험사 해킹과 정보보호"},"jobs":["리스크관리"],"companies":["미래에셋생명"],"figs":[{"type":"timeline","title":"미래에셋생명 해킹, 지금까지의 흐름","items":[{"when":"10월 28일","label":"1차 유출 공지(이름·주민등록번호·계좌번호 등)"},{"when":"그 뒤","label":"퇴직연금 거래 정보와 2차 유출 정보 추가 확인"},{"when":"10월 30일","label":"현장점검 예정 종료일, 1차례 연장"},{"when":"11월 3일","label":"금감원장, 임원회의에서 최고경영자 책임 언급"},{"when":"11월 4일","label":"점검 장기화, 피해 규모 확정에 신중","now":true}],"look":"1차 공지 뒤 유출 범위가 넓어져 점검이 길어진 흐름을 봐요."}],"sources":[{"name":"파이낸셜뉴스","url":"https://www.fnnews.com/news/202611040958397625"}],"brief":{"what":"미래에셋생명 해킹 사고에 대한 금감원 현장점검이 10월 30일 종료 예정을 넘겨 길어지고 있어요.","why":"퇴직연금 거래 정보와 2차 유출 정보가 추가로 확인되면서 유출 범위가 넓어졌고, 금감원은 피해 규모 확정에 신중하기 때문이에요.","so":"보험사에 정보보호는 경영진이 책임지는 운영위험이 됐고, 피해 규모가 확정돼야 손해배상안이 나와서 **보상은 당장 나오기 어려워요**."},"pre":["현장점검","운영위험"]},{"id":"2026-11-04-3","date":"2026-11-04","tag":"해외 진출","title":"베트남 8곳·인도네시아 7곳, 금감원이 현지 감독당국을 서울로 부른 이유","predict":{"q":"6월 말 기준 베트남에서 영업 중인 국내 보험사는 몇 곳일까요?","options":["7곳","8곳","15곳"],"answer":1,"reveal":"**8곳**이고, 인도네시아에는 7곳이 있어요. 금감원은 두 나라 보험감독당국의 인허가 담당자를 초청해 세미나와 실무간담회를 열고 **국내 보험사의 현지 애로사항을 직접 전달**했어요."},"numbers":[{"label":"베트남 영업 국내 보험사","value":"8곳","note":"2026년 6월 말"},{"label":"인도네시아 영업 국내 보험사","value":"7곳","note":"2026년 6월 말"},{"label":"세미나 참석","value":"50여 명","note":"협회·보험개발원·보험사 임직원"}],"points":["금감원이 베트남과 인도네시아 보험감독당국의 인허가 담당자 등을 초청해 세미나를 열었어요. 두 나라 관계자들이 **보험시장 현황과 전망, 최근 인허가와 감독 현안**을 설명했어요.","별도 실무간담회에서는 감독 체계와 제도 운영 경험을 나누고, 국내 보험사들이 겪는 **인허가·영업 애로사항과 건의사항**을 전달하며 감독당국 사이의 협조를 요청했어요.","이세훈 수석부원장은 국내 보험사가 현지 법과 제도를 지키며 안정적으로 사업을 넓히도록 지원하겠다고 밝혔어요."],"why":"해외 진출은 상품을 그대로 옮기는 일이 아니에요. 나라마다 **인허가 절차, 상품 규제, 감독 기준**이 달라서 같은 상품도 다시 설계해야 할 때가 많아요. 그래서 현지 감독당국과의 소통은 영업만큼 중요한 기반이에요. 상품개발·계리 관점에서는 현지의 사망률, 질병 통계, 판매 채널이 국내와 다르다는 점을 먼저 떠올려야 해요. 이런 뉴스를 볼 땐 \"이 시장에서 우리 상품의 어떤 가정이 달라질까\"를 생각해보세요.","chain":["국내 보험사가 베트남 8곳, 인도네시아 7곳에서 영업","나라마다 인허가와 감독 제도가 다름","금감원이 현지 감독당국을 초청해 세미나 개최","시장 현황·인허가 현안 공유와 애로사항 전달","감독당국 사이의 협조 체계가 생김","국내 보험사의 현지 사업 안정성이 높아질 수 있음"],"role":{"q":"당신은 생명보험사 해외사업팀 신입이에요. 팀장님이 묻습니다. \"국내에서 잘 팔린 건강보험을 베트남에 내려면 무엇부터 확인해야 할까?\" 순서대로 말해보세요.","model":"먼저 **현지 인허가와 상품 규제**를 확인해야 해요. 어떤 보장을 넣을 수 있는지, 상품 심사는 어떻게 받는지가 나라마다 달라요. 다음은 **보험료 계산의 기초 통계**예요. 국내 질병 발생률을 그대로 쓰면 안 되고, 현지 통계나 경험 자료로 위험률을 다시 잡아야 해요. 그다음 현지에서 보험이 주로 팔리는 **판매 채널**과 그에 따른 사업비, 해지율을 따져봐야 해요. 이번 세미나처럼 감독당국과 직접 소통할 기회가 있으면 인허가 현안을 미리 파악하는 데 큰 도움이 돼요."},"summary":"우리나라 보험사들이 베트남이랑 인도네시아에서 장사를 많이 하니까, 금감원이 그 나라 감독기관 사람들을 불러서 규칙도 듣고 애로사항도 전했어.","interview":{"q":"국내 보험사의 동남아 진출에서 가장 중요한 성공 요인은 무엇이라고 보나요?","guide":"결론부터: 현지 제도 이해와 현지 위험에 맞춘 상품 설계가 가장 중요하다고 말해요.\n근거: 6월 말 기준 베트남 8곳, 인도네시아 7곳의 국내 보험사가 영업 중이고, 금감원이 두 나라 감독당국을 초청해 인허가 현안과 애로사항을 공유했어요.\n관점: 계리·상품 관점에서 현지 통계로 위험률을 다시 잡고, 판매 채널에 맞춰 사업비·해지율 가정을 세워야 한다고 덧붙여요.\n마무리: 국내 경험을 현지 실정에 맞게 바꾸는 역할을 해보고 싶다고 마무리해요."},"quiz":[{"q":"6월 말 기준 인도네시아에서 영업 중인 국내 보험사 수는?","o":["8곳","15곳","7곳"],"a":2,"e":"베트남 8곳, 인도네시아 7곳이에요."},{"q":"실무간담회에서 국내 보험사들이 전달한 것은?","o":["국내 보험사의 현지 판매 실적 자료","인허가·영업 애로사항과 건의사항","국내 보험시장 현황과 전망"],"a":1,"e":"현지 사업을 하며 겪는 인허가와 영업의 어려움, 건의사항을 전했어요."},{"q":"국내 상품을 해외에 낼 때 계리 관점에서 꼭 다시 잡아야 하는 것은?","o":["현지 통계에 맞춘 위험률","국내 상품의 보험료 수준 그대로","본사의 국내 지급여력비율"],"a":0,"deep":true,"e":"질병·사망 발생률은 나라마다 달라서 현지 자료로 위험률을 다시 잡아야 해요."}],"terms":[{"t":"인허가","d":"회사가 영업을 하거나 상품을 팔기 전에 감독당국에서 받아야 하는 허락이에요."},{"t":"감독당국","d":"금융회사가 법과 규칙을 지키는지 살피고 관리하는 기관이에요. 우리나라는 금융위원회와 금융감독원이에요."},{"t":"위험률","d":"사고나 질병이 생길 확률로, 보험료를 계산하는 기초가 돼요."}],"thread":{"id":"overseas","name":"보험사 해외 진출"},"jobs":["상품개발","계리"],"figs":[{"type":"bars","title":"동남아에서 영업 중인 국내 보험사","unit":"곳","items":[{"label":"베트남","value":8,"hi":true},{"label":"인도네시아","value":7}],"note":"2026년 6월 말 기준이에요.","look":"베트남 8곳, 인도네시아 7곳으로 베트남이 한 곳 더 많아요."}],"sources":[{"name":"아주경제","url":"https://www.ajunews.com/view/20261104093921226"}],"brief":{"what":"금감원이 베트남과 인도네시아 보험감독당국 담당자를 서울로 초청해 세미나와 실무간담회를 열었어요. 6월 말 기준 국내 보험사는 베트남 8곳, 인도네시아 7곳에서 영업 중이에요.","why":"나라마다 인허가 절차와 감독 기준이 달라, 현지에서 겪는 어려움을 감독당국끼리 풀어야 하기 때문이에요.","so":"국내 보험사는 현지 인허가 현안을 미리 파악할 수 있고, 계리·상품개발은 **현지 통계로 위험률을 다시 잡아야** 해요."},"pre":["인허가","위험률"]},{"id":"2026-11-04-4","date":"2026-11-04","tag":"인수합병","title":"2조 원을 바랐던 롯데손해보험, 6,933억 원에 신한금융 품으로","predict":{"q":"2024년 매각 측은 롯데손해보험 지분 77.04%의 몸값으로 2조~3조 원을 바랐다고 알려졌어요. 10월 13일 신한금융과 맺은 계약 금액은 어땠을까요?","options":["희망가보다 크게 낮은 6,933억 원","희망가 수준인 2조 원대","희망가에 못 미치는 약 1조 2,000억 원"],"answer":0,"reveal":"신한금융은 지분 77.04%를 **6,933억 원**에 사기로 했어요. 매각이 길어지는 동안 기본자본 지급여력비율이 마이너스로 떨어지고 경영개선요구까지 받으면서, 인수 뒤 들어갈 **자본 확충 부담**이 가격에 반영된 거예요."},"comic":{"title":"몸값이 깎인 이유","panels":[{"caption":"매각을 시작할 땐 기대가 컸어요","bg":"office","board":"up","chars":[{"who":"insurer","mood":"happy","pose":"cheer","fx":"sparkle","say":"우리 몸값은 2조 원 이상!"}]},{"caption":"그런데 기본자본 비율이 마이너스","bg":"meeting","sign":"기본자본 비율 −5.4%","chars":[{"who":"regulator","mood":"worried","pose":"doc","say":"자본의 질부터 채우세요"},{"who":"insurer","mood":"surprised","pose":"worry","fx":"sweat"}]},{"caption":"결국 계약서에 적힌 숫자는","bg":"focus","sign":"6,933억 원","chars":[{"who":"insurer","mood":"sad","pose":"shrug","fx":"gloom","say":"기대의 3분의 1 수준이네…"}]},{"caption":"망고 계리사의 정리","bg":"meeting","board":"flat","chars":[{"who":"mango","mood":"thinking","pose":"point","fx":"idea","say":"인수 뒤 증자와 수익 회복이 진짜 숙제예요"}]}]},"figs":[{"type":"timeline","title":"롯데손해보험이 신한금융에 팔리기까지","items":[{"when":"2025년 11월","label":"금융위, 경영개선권고"},{"when":"2026년 3월","label":"경영개선요구 대상 지정"},{"when":"2026년 5월","label":"수정 경영개선계획 조건부 승인(1년 6개월 이행)"},{"when":"2026년 6월 말","label":"기본자본 지급여력비율 −5.4%"},{"when":"2026년 10월 13일","label":"신한금융, 지분 77.04%를 6,933억 원에 인수 계약","now":true},{"when":"앞으로","label":"잔여 지분 22.96% 확보 후 신한이지손해보험과 통합"}],"look":"경영개선권고에서 시작해 2026년 10월 13일 신한금융 인수 계약까지 이어져요."},{"type":"bars","title":"인수 비용, 계약금만 보면 안 돼요","unit":"억 원","items":[{"label":"지분 77.04% 계약 금액","value":6933,"text":"6,933억 원","hi":true},{"label":"잔여 지분 22.96%(같은 주당 가격)","value":2066,"text":"약 2,066억 원"},{"label":"거론되는 유상증자","value":3000,"text":"약 3,000억 원"}],"note":"세 금액을 더한 초기 총투자액은 약 1조2,000억 원으로 추산돼요(아이뉴스24). 증권가에서는 정상화 비용까지 1조5,000억~2조 원이 들 수 있다고 봐요.","look":"계약금 6,933억 원에 잔여 지분 약 2,066억 원, 유상증자 약 3,000억 원이 더해져요."}],"numbers":[{"label":"인수 지분","value":"77.04%","note":"제이케이엘파트너스 보유분"},{"label":"계약 금액","value":"6,933억 원","note":"주당 2,900원"},{"label":"기본자본 지급여력비율","value":"−5.4%","note":"2026년 6월 말"},{"label":"보험계약마진","value":"2조2,431억 원","note":"2분기 말, 1분기 말 2조5,090억 원에서 감소"}],"points":["신한금융지주가 10월 13일 사모펀드 제이케이엘파트너스가 가진 롯데손해보험 지분 **77.04%를 6,933억 원**에 사는 계약을 맺었어요. 금융당국 승인을 거쳐 남은 지분 22.96%도 확보해 완전자회사로 만든 뒤 신한이지손해보험과 합칠 계획이에요.","롯데손해보험은 고객 약 334만 명과 설계사 영업망을 가졌지만, 올해 상반기 185억 원 순손실을 냈고 6월 말 **기본자본 지급여력비율이 −5.4%**예요. 보험계약마진도 1분기 말 2조5,090억 원에서 2분기 말 2조2,431억 원으로 줄었어요.","신한금융은 외부 조달 없이 그룹 자본을 옮겨 쓰고, 통합 뒤 3년 안에 **연간 1,200억 원 이상**을 그룹 손익에 보태겠다는 목표를 내놨어요."],"why":"보험사 인수 가격은 '지금 이익'보다 **'앞으로 넣어야 할 자본'**에 크게 좌우돼요. 롯데손해보험은 전체 지급여력비율보다 자본의 질을 보는 기본자본 비율이 마이너스여서, 인수자는 계약금 말고도 잔여 지분 매입과 유상증자 비용을 함께 계산해야 했어요. 은행 중심 금융그룹이 비은행 이익을 늘리려고 보험사를 사는 흐름도 읽을 수 있어요. 계리 관점에서는 줄어드는 **보험계약마진의 원인**(손해율 가정 변경, 해지 증가 등)을 따져야 인수 뒤 수익성이 언제 회복될지 가늠할 수 있어요. 기사에 나온 전문가는 조직 안정화에 5~10년이 걸릴 수 있다고 봤어요.","chain":["롯데손보 기본자본 비율 마이너스","경영개선권고에 이어 경영개선요구","매각 장기화로 몸값 하락","신한금융, 6,933억 원에 지분 77.04% 인수","잔여 지분 매입·증자로 총투자 확대","신한이지손보와 통합해 손보 사업 재편"],"role":{"q":"당신은 금융지주 보험사업 전략팀 신입이에요. 상무님이 묻습니다. \"6,933억 원이면 싸게 산 거 아닌가? 왜 증권사들은 총비용이 2조 원까지 갈 수 있다고 하지?\" 계약금과 실제 부담의 차이를 설명해보세요.","model":"계약금 6,933억 원은 지분 77.04%의 값일 뿐이다. 완전자회사로 만들려면 같은 주당 가격 기준으로 잔여 지분에 약 2,066억 원이 더 들고, 기본자본 지급여력비율이 −5.4%라 **규제 기준을 맞추기 위한 유상증자**도 필요하다(약 3,000억 원 거론). 그래서 초기 총투자액은 약 1조2,000억 원으로 추산되고, 수익성이 늦게 회복되면 정상화 비용까지 1조5,000억~2조 원으로 커질 수 있다. 결국 '싸게 샀는지'는 **보험계약마진 감소를 멈추고 보험손익을 얼마나 빨리 회복하느냐**에 달려 있다고 보고해야 한다."},"summary":"신한금융이 롯데손해보험을 6,933억 원에 사기로 했어. 원래 2조 원 넘게 받고 싶어 했는데, 자본 상태가 나빠서 값이 확 떨어졌고, 신한은 앞으로 증자 같은 돈을 더 넣어야 해.","interview":{"q":"신한금융이 롯데손해보험을 인수했습니다. 인수한 쪽 입장에서 가장 먼저 챙겨야 할 과제는 무엇이라고 보나요?","guide":"결론부터: 자본의 질을 회복하고 보험계약마진 감소를 멈추는 것이 먼저라고 봐요.\n근거: 롯데손해보험은 6월 말 기본자본 지급여력비율이 −5.4%이고, 보험계약마진이 한 분기 만에 2조5,090억 원에서 2조2,431억 원으로 줄었어요. 계약금 6,933억 원에 잔여 지분과 증자를 더하면 초기 투자만 약 1조2,000억 원으로 추산돼요.\n관점: 계리 쪽에서는 보험계약마진이 왜 줄었는지 손해율·해지율 가정을 다시 점검하고, 상품개발 쪽에서는 신한이지손해보험과 겹치는 상품을 정리해 수익성 높은 장기보장성 위주로 재편해야 해요.\n마무리: 3년 안에 1,200억 원 이익 기여라는 목표도 이 두 숫자가 개선돼야 가능하다고 정리할게요."},"quiz":[{"q":"신한금융이 10월 13일 계약으로 사기로 한 롯데손해보험 지분과 금액은?","o":["지분 100%, 6,933억 원","지분 77.04%, 약 1조 2,000억 원","지분 77.04%, 6,933억 원"],"a":2,"e":"제이케이엘파트너스가 가진 **77.04%를 6,933억 원**에 사는 계약이에요. 남은 22.96%는 승인을 거쳐 따로 확보할 계획이에요."},{"q":"롯데손해보험의 몸값이 크게 낮아진 가장 큰 이유로 알맞은 것은?","o":["기본자본 지급여력비율이 마이너스여서 인수 뒤 자본 확충 부담이 커서","보험계약마진이 늘어 미래 이익이 이미 가격에 모두 반영돼서","설계사 영업망이 없어 신한이지손해보험과 합치기 어려워서"],"a":0,"e":"6월 말 기본자본 비율이 −5.4%였고 경영개선요구까지 받았어요. 인수자는 **증자 부담**을 가격에 반영해요."},{"q":"잔여 지분 22.96%를 같은 주당 가격(2,900원)으로 산다면 약 얼마가 더 들까요?","o":["약 1,200억 원","약 2,066억 원","약 3,000억 원"],"a":1,"e":"기사 계산으로 약 **2,066억 원**이에요. 그래서 계약금만 보고 인수 비용을 판단하면 안 돼요.","deep":true}],"terms":[{"t":"기본자본 지급여력비율","d":"보완자본을 빼고 기본자본만으로 계산한 지급여력비율이에요. 자본의 질을 보여줘요."},{"t":"경영개선요구","d":"재무 건전성이 나쁜 금융회사에 금융당국이 내리는 적기시정조치 가운데 두 번째 단계예요. 경영개선권고보다 강해요."},{"t":"완전자회사","d":"모회사가 지분 100%를 가진 자회사예요. 상장된 회사라면 남은 주식을 모두 사들여 상장을 폐지하게 돼요."},{"t":"유상증자","d":"회사가 새 주식을 발행해 돈을 받고 팔아 자본을 늘리는 방법이에요."},{"t":"보험계약마진","d":"보험계약에서 앞으로 나눠서 이익으로 인식할, 아직 실현되지 않은 이익이에요."}],"thread":{"id":"insurer-mna","name":"보험사 인수합병과 사업 확장"},"jobs":["계리","리스크관리"],"companies":["롯데손해보험"],"sources":[{"name":"CEO스코어데일리","url":"https://m.ceoscoredaily.com/page/view/2026101314072296475"},{"name":"SBS Biz","url":"https://biz.sbs.co.kr/amp/article/20000339857"},{"name":"아이뉴스24","url":"https://www.inews24.com/view/2015407"}],"brief":{"what":"신한금융지주가 10월 13일 롯데손해보험 지분 77.04%를 6,933억 원에 사는 계약을 맺었어요.","why":"롯데손해보험은 6월 말 기본자본 지급여력비율이 −5.4%로 떨어지고 경영개선요구까지 받아, 인수 뒤 들어갈 자본 확충 부담이 가격에 반영됐어요.","so":"잔여 지분 22.96%와 유상증자까지 더하면 초기 총투자액이 **약 1조2,000억 원**으로 추산돼요. 신한금융은 통합 뒤 3년 안에 연간 1,200억 원 이상을 그룹 손익에 보태겠다는 목표를 내놨어요."},"pre":["기본자본 지급여력비율","경영개선요구"]},{"id":"2026-11-04-5","date":"2026-11-04","tag":"기후·재해","title":"35도가 넘으면 바로 지급? 보험연구원이 꺼낸 '지수형 기후보험'","predict":{"q":"폭염으로 장사가 안 된 소상공인처럼, 물건이 부서지지 않았는데 매출만 준 피해는 기존 실손형 보험으로 보상받기 쉬울까요?","options":["쉽다, 실손형은 매출 감소분도 손실로 쉽게 인정한다","쉽다, 정책성 보험은 정해진 금액을 바로 지급한다","어렵다, 실손형은 실제 손실을 산정해야 해서 보장 공백이 생긴다"],"answer":2,"reveal":"기존 정책성 보험(농작물재해보험, 풍수해보험 등)은 모두 **손실을 계산해 비례 지급하는 실손형**이에요. 매출 감소처럼 계산이 어려운 피해는 빠지기 쉬워서, 보험연구원은 기상 지표만 충족하면 바로 지급하는 **지수형 보험**으로 공백을 메우자고 했어요."},"figs":[{"type":"compare","title":"실손형과 지수형, 무엇이 다를까","left":"실손형","right":"지수형","rows":[{"label":"보험금 기준","left":"실제 손실액을 산정해 비례 지급","right":"기온 같은 기상 지표가 조건을 넘으면 정해진 금액 지급"},{"label":"지급 속도","left":"손해사정이 필요해 느림","right":"조건 충족 즉시"},{"label":"약점","left":"매출 감소 같은 간접 피해는 보장 공백","right":"지급액이 실제 손실과 다를 수 있음"},{"label":"국내 예","left":"농작물재해보험, 풍수해보험","right":"제주도 건설 일용직 폭염보험(35도 이상 이틀 연속 예보 기준)"}],"note":"보험연구원은 지수형이 실손형을 대체하는 게 아니라 보완해야 한다고 했어요.","look":"지수형은 기온 같은 지표 조건을 넘으면 정해진 금액을 바로 지급해요."},{"type":"bars","title":"기업성 보험에서 중소기업이 차지하는 비중","unit":"%","items":[{"label":"한국","value":34,"text":"34%","hi":true},{"label":"해외","value":60,"text":"60% 이상"}],"note":"보험연구원 한진현 연구위원 발표(2026년 10월 13일) 기준이에요.","look":"기업성 보험의 중소기업 비중은 한국 34%, 해외 60% 이상이에요."}],"numbers":[{"label":"소상공인 풍수해보험 가입률","value":"4.6%","note":"기사 부제 기준"},{"label":"경기도 기후취약계층","value":"약 22만 명","note":"자동 가입, 진단 시 15만 원 정액 지급"},{"label":"제주 폭염보험 기준","value":"35도","note":"일 최고기온 35도 이상이 이틀 연속 예상될 때"},{"label":"기업성 보험 중 중소기업 비중","value":"34%","note":"해외는 60% 이상"}],"points":["보험연구원이 10월 13일 세미나에서 기후위기로 자연재해가 커지면서 **기존 실손형 보험이 못 메우는 보장 공백**이 넓어지고 있다고 진단했어요. 소상공인의 풍수해보험 가입률은 4.6%에 그쳐요.","**지수형 보험**은 손실액을 계산하지 않고, 예를 들어 기온이 35도를 넘으면 미리 정한 금액을 바로 지급해요. 대신 지급액이 실제 손실과 다를 수 있어서 실손형을 유지하면서 빈 곳을 보완하자는 제안이에요.","국내에선 경기도(자동 가입, 진단 시 15만 원), 제주도(건설 일용직 폭염), 전통시장 날씨 피해 보상보험 같은 사례가 나왔고, 해외는 소득·거주 지역·산업군 등 여러 기준으로 취약계층을 나눠 보장한다는 점이 비교됐어요."],"why":"지수형 보험은 상품개발자에게 **'무엇을 지급 조건으로 삼을까'**라는 새 질문을 던져요. 기온, 강수량, 풍속 같은 지표와 실제 피해 사이의 차이(기저위험)를 줄이도록 지표와 기준선을 설계하는 게 핵심이에요. 손해사정이 필요 없어서 빠르게 지급할 수 있지만, 지표는 넘었는데 피해가 없거나 반대로 피해가 났는데 지표가 안 넘는 경우가 생길 수 있어요. 또 새로운 기후위험은 통계가 부족해 민간이 처음부터 값을 매기기 어렵기 때문에, 발표자는 **초기엔 정부가 위험을 일부 나누고 점차 민간 시장으로 넘기는** 방향을 제안했어요. 앞으로 기후보험 뉴스를 볼 때 '누가 위험을 지고, 무엇으로 지급을 정하는지'를 먼저 보세요.","chain":["기후위기로 자연재해 피해 확대","실손형 보험은 손실 산정이 어려운 피해를 못 메움","매출 감소 같은 보장 공백 증가","기상 지표로 바로 지급하는 지수형 보험 제안","초기엔 정부가 위험 분담","점차 민간 시장이 위험 인수"],"role":{"q":"당신은 손해보험사 상품개발팀 신입이에요. 팀장님이 묻습니다. \"전통시장 상인용 폭염 지수형 보험을 만든다면, 보험금 지급 조건을 어떻게 잡을지 생각해봤어?\" 설계할 때 따져야 할 점을 설명해보세요.","model":"먼저 상인의 매출 감소와 가장 잘 맞는 지표를 골라야 한다. 일 최고기온이 몇 도 이상이 며칠 이어질 때 매출이 실제로 줄었는지 **과거 기상 자료와 매출 자료를 맞대어** 기준선을 정한다. 지표와 실제 손실이 어긋나는 **기저위험**을 줄이려면 시장 가까운 관측소 자료를 쓰고, 지급액도 평균 손실 규모에 맞춰야 한다. 마지막으로 폭염 일수가 해마다 늘고 있다면 과거 평균으로만 요율을 잡지 말고 추세를 반영해야 하고, 통계가 부족하면 지자체 시범사업처럼 위험을 나누는 구조도 검토할 수 있다."},"summary":"폭염 때문에 장사가 안 돼도 기존 보험은 손해를 계산하기 어려워서 보상이 잘 안 돼. 그래서 보험연구원이 기온이 35도를 넘는 것처럼 조건만 맞으면 바로 돈을 주는 지수형 보험을 늘리자고 했어.","interview":{"q":"기후위기 시대에 보험사가 새로 만들 수 있는 상품으로 지수형 보험이 거론됩니다. 장점과 한계를 어떻게 보나요?","guide":"결론부터: 지수형 보험은 실손형이 못 메우는 간접 피해를 빠르게 보장할 수 있지만, 지표와 실제 손실의 차이를 관리하는 게 관건이라고 봐요.\n근거: 보험연구원은 소상공인 풍수해보험 가입률이 4.6%에 그치고, 기업성 보험 중 중소기업 비중이 34%로 해외(60% 이상)보다 낮다고 했어요. 제주도는 35도 이상 폭염이 이틀 연속 예보되면 지급하는 보험을 도입했어요.\n관점: 상품개발자는 과거 기상·손실 자료로 지급 기준선을 정하고, 기온 상승 추세를 요율에 반영해야 해요.\n마무리: 초기에는 정부와 위험을 나누고 통계가 쌓이면 민간이 가격을 정하는 단계적 접근이 현실적이라고 말하겠어요."},"quiz":[{"q":"지수형 보험의 보험금 지급 방식으로 옳은 것은?","o":["손해사정으로 실제 손실을 산정해 비례 지급","기상 지표가 정해진 조건을 넘으면 미리 정한 금액 지급","기상 지표가 조건을 넘고 피해가 확인되면 정해진 금액 지급"],"a":1,"e":"지수형은 **손실 산정 없이** 지표 조건으로 지급해요. 그래서 빠르지만 실제 손실과 다를 수 있어요."},{"q":"보험연구원 발표에서 소상공인의 풍수해보험 가입률은?","o":["34%","14.6%","4.6%"],"a":2,"e":"**4.6%**에 그쳐 보장 공백이 크다는 지적이에요. 34%는 기업성 보험 중 중소기업 비중이에요."},{"q":"지수형 보험에서 지표는 조건을 넘었는데 실제 피해가 없거나, 피해가 났는데 지표가 안 넘는 위험을 줄이는 방법으로 가장 알맞은 것은?","o":["피해 지역 가까운 관측 자료와 과거 손실 자료로 지표와 기준선을 설계한다","지급 기준선을 높게 정해 지급 건수를 최대한 줄인다","지급액을 가입자가 사고 뒤에 직접 정하게 한다"],"a":0,"e":"이런 차이를 **기저위험**이라고 해요. 지표를 실제 손실과 잘 맞게 고르는 게 상품 설계의 핵심이에요.","deep":true}],"terms":[{"t":"지수형 보험","d":"기온, 강수량 같은 지표가 미리 정한 조건을 넘으면 손실 산정 없이 정해진 보험금을 바로 주는 보험이에요."},{"t":"실손형 보험","d":"실제로 생긴 손실액을 계산해 그만큼(또는 비례해서) 보상하는 보험이에요."},{"t":"기저위험","d":"지수형 보험에서 지표로 정한 보험금과 실제 손실이 서로 어긋날 위험이에요."},{"t":"풍수해보험","d":"태풍, 홍수, 호우 같은 자연재해로 생긴 주택·상가 피해를 보상하는 정책성 보험이에요. 정부가 보험료 일부를 지원해요."}],"thread":{"id":"climate-insurance","name":"기후위기와 보험"},"jobs":["상품개발","계리"],"sources":[{"name":"CEO스코어데일리","url":"https://ceoscoredaily.com/page/view/2026101315382227824"}],"brief":{"what":"보험연구원이 10월 13일 세미나에서 기후위기로 커지는 자연재해에 대응해, 기상 지표가 조건을 넘으면 정해진 금액을 바로 지급하는 지수형 보험을 제안했어요.","why":"기존 정책성 보험은 손실을 계산해 비례 지급하는 실손형이라 매출 감소 같은 간접 피해는 보장 공백이 생기고, 소상공인의 풍수해보험 가입률도 4.6%에 그쳐요.","so":"지수형은 손해사정 없이 빠르게 지급하지만 지급액이 실제 손실과 다를 수 있어서, 상품개발자는 **지표와 기준선을 설계**해야 해요. 초기에는 정부가 위험을 일부 나누는 방식도 제안됐어요."},"pre":["지수형 보험","실손형 보험"]},{"id":"2026-11-04-6","date":"2026-11-04","tag":"상품개발","title":"'700종신'이 사라진 자리, 생보사들은 '인출'로 종신보험을 다시 짰다","predict":{"q":"7년 뒤 낸 보험료를 100% 넘게 돌려주던 '700종신'이 9월 판매 중단된 뒤, 생보사들은 어떤 방향으로 종신보험을 바꿨을까요?","options":["사망보장을 줄이는 대신 환급률을 더 높인 단기납 종신보험","사망보장을 없애고 낸 보험료를 만기에 모두 돌려주는 저축형 보험","사망보장은 지키면서 납입보험료를 생애자금으로 꺼내 쓰게 하는 종신보험"],"answer":2,"reveal":"삼성생명은 골든종신보험의 **인출 시점을 2년 앞당기고 암보장형**을 넣었고, 한화생명은 **납입보험료 전액을 생애자금으로 인출**하면서도 사망보장을 종신까지 유지하는 상품을 내놨어요. 환급률 경쟁 대신 '필요할 때 꺼내 쓰는' 구조로 방향을 바꾼 거예요."},"comic":{"title":"환급률 대신 인출","panels":[{"caption":"잘 팔리던 700종신이 멈췄어요","bg":"office","sign":"700종신 판매 중단","chars":[{"who":"planner","mood":"surprised","pose":"phone","fx":"exclaim","say":"이제 뭘 팔죠?"}]},{"caption":"당국은 보장성보험이 저축처럼 팔리는 걸 걱정했어요","bg":"meeting","board":"down","chars":[{"who":"regulator","mood":"worried","pose":"point","say":"원금 도달 뒤 대량 해지가 걱정돼요"}]},{"caption":"보험사들이 새 구조를 내놨어요","bg":"home","chars":[{"who":"insurer","mood":"happy","pose":"doc","fx":"sparkle","say":"낸 돈 꺼내 써도 사망보장은 유지!"},{"who":"carrot","mood":"thinking","pose":"think","fx":"question","say":"그럼 해지 안 해도 되겠네?"}]},{"caption":"망고 계리사의 정리","bg":"meeting","board":"flat","chars":[{"who":"mango","mood":"thinking","pose":"point","fx":"idea","say":"인출 뒤 사망보장과 적립금 흐름을 잘 맞춰야 해요"}]}]},"figs":[{"type":"compare","title":"700종신 이후 새로 나온 종신보험","left":"삼성생명 골든종신(10월 14일 개정)","right":"한화생명 필요할때 쓰는 종신(10월 14일 출시)","rows":[{"label":"인출 기능","left":"인출 가능 시점 단축(7년납 12년→10년, 10년납 14년→12년)","right":"납입보험료 전액을 생애자금으로 한 번에 또는 2~8년에 걸쳐 인출"},{"label":"사망보장","left":"인출 후에도 최초 가입금액 이상 유지","right":"10년납 기준 최대 210%까지 체증, 인출 후에도 종신 유지"},{"label":"새 기능","left":"암보장형: 납입 중 암 진단 시 남은 보험료 면제, 납입보험료 최대 100% 추가 인출","right":"인출 시기를 계약 20년 시점 안에서 고객이 정함"},{"label":"가입","left":"만 15~65세, 7·10·15·20년납","right":"최대 65세, 10년납 또는 12년납"}],"note":"SBS Biz 2026년 10월 13·14일 기사 기준이에요.","look":"삼성은 인출 시점을 2년 앞당기고, 한화는 납입보험료 전액 인출을 붙였어요."},{"type":"timeline","title":"종신보험 판매 경쟁의 흐름","items":[{"when":"2025년 9월","label":"삼성생명 골든종신보험 첫 출시"},{"when":"2026년 9월 21일","label":"700종신 신규 판매 사실상 중단"},{"when":"2026년 10월 14일","label":"삼성생명 골든종신 개정·한화생명 필요할때 쓰는 종신 출시","now":true},{"when":"2026년 10월 15일","label":"흥국생명, 납입보험료를 노후에 매월 돌려주는 종신보험 출시"}],"look":"700종신 중단 뒤 10월 14일과 15일에 새 종신보험이 잇따라 나왔어요."}],"numbers":[{"label":"한화생명 사망보험금 체증","value":"최대 210%","note":"10년납 기준"},{"label":"삼성생명 인출 시점 단축","value":"2년","note":"7년납 12년→10년"},{"label":"암보장형 추가 인출","value":"최대 100%","note":"납입보험료 기준"},{"label":"700종신 환급 구조","value":"7년 뒤 100%","note":"판매 중단된 상품"}],"points":["7년 뒤 낸 보험료를 100% 넘게 돌려주던 **700종신**은 유지율이 낮고 원금 도달 직후 대량 해지가 나면 건전성이 나빠질 수 있다는 당국 우려로 9월 21일부터 사실상 판매가 멈췄어요.","삼성생명은 골든종신보험의 인출 가능 시점을 2년씩 앞당기고, 납입 중 암에 걸리면 남은 보험료를 면제하고 납입보험료의 최대 100%를 추가로 꺼내 쓰는 **암보장형**을 넣었어요.","한화생명은 사망보험금이 **최대 210%까지 늘어나는 체증형**에 납입보험료 전액을 생애자금으로 인출하는 기능을 붙였어요. 다 꺼내 써도 남은 사망보장은 종신까지 유지돼요."],"why":"단기납 종신보험의 높은 환급률 경쟁이 막히자, 보험사들은 **'해지하지 않고 꺼내 쓰는'** 구조로 저축 수요를 붙잡으려 하고 있어요. 계리 관점에서 해지는 한꺼번에 돈이 빠져나가는 사건이지만, 인출은 계약을 유지하면서 일부만 나가는 거라 **해지율 가정과 현금흐름**이 완전히 달라져요. 동시에 인출 후에도 사망보장을 유지한다면 그 보장의 원가를 어떻게 맞출지, 체증형 사망보험금이 사망률 가정에 얼마나 민감한지도 따져야 해요. 당국이 '보장성보험이 저축처럼 팔리는 것'을 문제 삼았던 만큼, 새 상품들이 같은 지적을 피할 수 있을지도 지켜볼 점이에요.","chain":["700종신, 낮은 유지율과 대량 해지 우려","9월 21일 신규 판매 사실상 중단","생보사, 대체 종신보험 필요","환급률 대신 생애자금 인출 기능 강화","삼성 암보장형·한화 체증형 출시","해지율·사망률 가정 다시 설계"],"role":{"q":"당신은 생명보험사 상품개발팀 신입이에요. 팀장님이 묻습니다. \"700종신은 환급률로 팔았는데, 새 상품은 인출로 팔겠다는 거잖아. 계리적으로 뭐가 달라지는지 정리해봐.\" 차이를 설명해보세요.","model":"700종신은 7년 시점에 환급률이 100%에 닿는 순간 **해지가 몰릴 위험**이 컸다. 해지는 적립금이 한꺼번에 빠지고 남은 계약의 보험계약마진도 사라지는 사건이다. 인출형은 계약을 유지한 채 나눠서 돈이 나가므로 해지율은 낮아질 수 있지만, 인출 뒤에도 사망보장을 유지하는 비용과 **인출 시기·규모에 대한 고객 선택**을 가정에 넣어야 한다. 한화생명처럼 사망보험금이 210%까지 늘어나면 사망률 가정이 조금만 틀려도 손익이 크게 흔들리므로 민감도 분석이 필요하다. 마지막으로 당국이 저축성 판매를 문제 삼았으니, 판매 자료가 저축 상품처럼 보이지 않도록 설계와 안내를 함께 점검해야 한다."},"summary":"7년 지나면 낸 돈 다 돌려주던 종신보험이 판매 중단되자, 삼성생명이랑 한화생명이 사망보장은 그대로 두고 낸 보험료를 나중에 꺼내 쓸 수 있는 종신보험을 새로 내놨어.","interview":{"q":"700종신 판매 중단 뒤 생보사들이 인출 기능을 강화한 종신보험을 내놓고 있습니다. 한화생명이나 삼성생명 입장이라면 이 상품의 위험을 어떻게 관리하겠습니까?","guide":"결론부터: 인출 행동과 체증형 사망보장이라는 두 가지 가정을 가장 꼼꼼히 관리하겠어요.\n근거: 한화생명 상품은 납입보험료 전액을 2~8년에 걸쳐 인출하면서도 사망보험금이 최대 210%까지 늘어나고, 삼성생명은 인출 시점을 2년 앞당기고 암 진단 시 최대 100% 추가 인출을 허용해요.\n관점: 계리는 고객이 언제 얼마나 인출할지를 경험통계로 추정하고, 체증형 사망보험금은 사망률 변화에 따른 민감도 분석을 해야 해요. 상품개발은 저축성으로 오해받지 않게 보장 기능을 중심에 둬야 해요.\n마무리: 판매 초기 인출·해지 실적을 가정과 비교해 빠르게 조정하는 체계가 중요하다고 정리하겠어요."},"quiz":[{"q":"700종신 판매가 사실상 중단된 이유로 기사에 나온 것은?","o":["원금 도달 직후 대량 해지가 나 건전성이 나빠질 수 있어서","사망보험금이 낮아 가입자 불만이 크게 늘어서","환급률이 100%에 못 미쳐 가입자가 대거 해지해서"],"a":0,"e":"당국은 7년 뒤 100% 환급 시점에 **해지가 몰리는 위험**을 걱정했어요."},{"q":"한화생명 '필요할때 쓰는 종신보험'의 특징으로 옳은 것은?","o":["암 진단 시 남은 보험료를 면제하고 납입보험료의 최대 100%를 추가 인출한다","사망보험금이 최대 210%까지 늘고 인출 후에도 사망보장이 종신까지 유지된다","인출하면 사망보장이 끝나는 대신 환급률이 210%까지 오른다"],"a":1,"e":"**체증형 사망보장 + 생애자금 인출**이 핵심이에요. 암보장형은 삼성생명 골든종신의 새 기능이에요."},{"q":"계리 관점에서 '해지'와 '인출'의 차이로 가장 알맞은 것은?","o":["인출도 해지와 같아서 계약이 끝나고 보험금 지급 의무도 사라진다","인출은 계약이 유지되므로 해지율 가정을 따로 세울 필요가 없다","인출은 계약이 유지된 채 일부만 나가서 해지율과 현금흐름 가정이 달라진다"],"a":2,"e":"인출형은 계약이 유지되므로 **해지율 가정**과 인출 시기·규모에 대한 가정을 따로 세워야 해요.","deep":true}],"terms":[{"t":"종신보험","d":"평생 보장하고, 언제 사망하든 정해진 사망보험금을 유족에게 주는 생명보험이에요."},{"t":"단기납 종신보험","d":"보험료를 5년, 7년처럼 짧게 내는 종신보험이에요. 납입이 끝난 뒤 환급률을 높게 설계해 저축처럼 팔리기도 했어요."},{"t":"체증형","d":"가입 뒤 시간이 지날수록 보험금이 정해진 비율로 늘어나는 구조예요."},{"t":"납입면제","d":"암 같은 정해진 사고가 생기면 남은 보험료를 내지 않아도 보장이 유지되는 기능이에요."},{"t":"해지율","d":"보험계약이 일정 기간 안에 중도 해지되는 비율이에요. 보험료와 보험부채 계산의 핵심 가정이에요."}],"thread":{"id":"product-competition","name":"보험상품 개발 경쟁"},"jobs":["상품개발","계리","영업·채널"],"companies":["삼성생명","한화생명","흥국생명"],"sources":[{"name":"SBS Biz","url":"https://biz.sbs.co.kr/amp/article/20000339659"},{"name":"SBS Biz","url":"https://biz.sbs.co.kr/amp/article/20000339972"},{"name":"머니투데이(서플)","url":"https://supple.kr/news/cmvcw8ycg000mjnvx3t6ibps8"}],"brief":{"what":"700종신이 9월 21일부터 사실상 판매가 멈춘 뒤, 삼성생명과 한화생명이 10월 14일 낸 보험료를 꺼내 쓰게 하는 종신보험을 내놨어요.","why":"당국이 유지율이 낮고 원금 도달 직후 대량 해지가 나면 건전성이 나빠질 수 있다고 우려했고, 생보사들은 환급률 경쟁 대신 해지하지 않고 꺼내 쓰는 구조로 저축 수요를 붙잡으려 해요.","so":"인출은 계약이 유지된 채 일부만 나가는 거라 **해지율 가정과 현금흐름이 달라져요**. 인출 후에도 사망보장을 유지하는 원가와 체증형의 사망률 민감도도 계리가 따져야 해요."},"pre":["단기납 종신보험","해지율"]},{"id":"2026-11-04-7","date":"2026-11-04","tag":"판매채널","title":"1200% 룰 밖에 있는 연금보험, 그래도 '차익거래'는 막으라는 금감원","predict":{"q":"1200% 룰과 차익거래 방지 기준은 원래 보장성보험에만 적용돼요. 700종신이 막힌 뒤 대안으로 떠오른 연금보험에 대해 금감원은 어떻게 했을까요?","options":["차익거래 방지 기준만 연금보험에 먼저 공식 적용했다","규정은 그대로 두되 보험사 스스로 차익거래를 관리하라고 주문했다","연금보험은 규제 대상이 아니어서 아무 주문도 하지 않았다"],"answer":1,"reveal":"금감원은 최근 생보사 검사에서 연금보험도 **자체적으로 차익거래 방지 관리 체계**를 만들라고 요구한 것으로 알려졌어요. 보장성 규제를 그대로 옮긴 게 아니라 **판매비용 내부통제**를 강화하라는 주문이에요."},"figs":[{"type":"compare","title":"보장성보험과 연금보험, 규제는 어떻게 다를까","left":"보장성보험(종신·통합건강 등)","right":"저축성 연금보험","rows":[{"label":"1200% 룰","left":"적용(첫해 수수료를 월 보험료의 12배 이내로)","right":"직접 적용 대상 아님"},{"label":"차익거래 방지 기준","left":"적용","right":"직접 적용 대상 아님"},{"label":"이번 금감원 주문","left":"-","right":"보험사 자체 차익거래 방지 관리 체계 마련"},{"label":"점검 방법(예)","left":"-","right":"모집수수료·시책·해약환급금과 누적 납입보험료를 계약별·회차별로 비교"}],"note":"보험저널 2026년 10월 15일 기사 기준이에요.","look":"연금보험은 1200% 룰이 직접 적용되지 않지만 자체 관리를 주문받아요."},{"type":"bars","title":"한 생보사 대리점 채널의 연금보험 시책 환수 예","unit":"%","items":[{"label":"일부 연금보험: 12회차 미유지","value":100,"text":"100% 환수","hi":true},{"label":"다른 연금보험: 13~24회차 미유지","value":50,"text":"50% 환수"}],"note":"납입기간과 지급 구분에 따라 달라요. 회차별 환수 기준만으로 차익거래 여부를 판단할 수는 없어요.","look":"12회차 미유지는 100% 환수, 13~24회차 미유지는 50% 환수예요."}],"numbers":[{"label":"12회차 미유지 시 환수","value":"100%","note":"일부 연금보험 시책"},{"label":"13~24회차 미유지 시 환수","value":"50%","note":"다른 연금보험 시책"},{"label":"1200% 룰 근거","value":"제4-32조","note":"보험업감독규정"}],"points":["700종신 판매가 위축되자 생보사와 법인보험대리점 채널에서 **1200% 룰 적용을 받지 않는 연금보험**이 대체 상품으로 떠오르고 있어요.","금감원은 생보사 검사 과정에서 연금보험도 모집수수료·시책·해약환급금을 누적 납입보험료와 **계약별·회차별로 비교**해, 판매보상과 환급금 합계가 납입보험료를 넘는 차익거래가 생기는지 스스로 점검하라고 주문했어요.","기사는 명목상 수수료 크기보다 **해지 시점에 환수액을 반영하고 실제로 남는 이익**이 얼마인지가 핵심이라고 봤어요."],"why":"**차익거래**는 수수료·시책과 해약환급금을 합친 돈이 낸 보험료보다 커서, 일찍 해지할수록 오히려 이득이 생기는 상황이에요. 이런 계약이 많아지면 보험사는 사업비를 쓰고도 계약이 금방 사라져 손해를 보고, 해지율 가정도 틀어져요. 규제 하나를 막으면 판매가 규제 밖 상품으로 옮겨 가는 **'풍선효과'**를 당국이 미리 막으려는 장면이에요. 상품개발과 계리 쪽에서는 연금보험의 해약환급금이 회차별로 어떻게 쌓이는지와 판매보상의 지급 시점을 함께 놓고, 어느 회차에서도 합계가 납입보험료를 넘지 않게 설계하는 게 중요해요.","chain":["700종신 판매 위축","1200% 룰 밖 연금보험이 대체 상품으로 부상","수수료·시책 경쟁 심화 우려","금감원, 연금보험도 자체 차익거래 관리 주문","계약별·회차별 판매보상과 환급금 비교","시책 지급 시기·환수 기준 조정 전망"],"role":{"q":"당신은 생명보험사 상품개발팀 신입이에요. 영업 담당 부장님이 말합니다. \"연금보험은 1200% 룰 대상도 아닌데, 왜 시책을 줄이라는 거야?\" 금감원 주문의 취지와 회사가 할 일을 설명해보세요.","model":"규정상 연금보험은 1200% 룰 대상이 아니지만, 수수료·시책과 해약환급금을 더한 금액이 누적 납입보험료를 넘으면 **일찍 해지할수록 이득인 차익거래**가 생긴다. 이런 계약은 사업비만 쓰고 금방 해지돼 회사 손익과 해지율 가정을 모두 흔든다. 그래서 금감원은 규정 확대가 아니라 **판매비용 내부통제** 차원에서 스스로 점검하라고 한 것이다. 회사는 상품별 해약환급금 곡선과 수수료·시책 지급 일정을 회차별로 맞대어 차익이 생기는 구간을 찾고, 그 구간의 시책 지급을 늦추거나 환수 기준을 손봐야 한다."},"summary":"보장성보험 수수료를 묶는 규칙이 연금보험에는 안 걸리니까 판매가 연금보험으로 몰릴 수 있잖아. 그래서 금감원이 연금보험도 수수료랑 환급금 합이 낸 돈보다 커지는 일이 없게 보험사가 알아서 관리하라고 했어.","interview":{"q":"금감원이 1200% 룰 대상이 아닌 연금보험에도 차익거래 관리를 주문했습니다. 이 조치를 어떻게 평가하나요?","guide":"결론부터: 규제 공백을 노린 판매 쏠림을 미리 막는 합리적인 조치라고 봐요.\n근거: 700종신이 위축되자 연금보험이 대체 상품으로 떠올랐고, 한 생보사는 12회차 미유지 시 시책 100%, 13~24회차 미유지 시 50%를 환수하는 기준을 두고 있어요.\n관점: 계리·상품개발은 해약환급금이 회차별로 쌓이는 속도와 수수료·시책 지급 시점을 비교해 어느 회차에서도 차익이 생기지 않게 설계해야 해요.\n마무리: 명목 수수료가 아니라 해지 시점의 실제 이익을 기준으로 관리하는 체계가 회사의 해지율 가정을 지키는 길이라고 말하겠어요."},"quiz":[{"q":"이 기사에서 말하는 차익거래 상태에 가장 가까운 것은?","o":["판매보상이 첫해 월 보험료의 12배를 넘는 상태","해약환급금이 누적 납입보험료보다 적은 상태","판매보상과 해약환급금 합계가 누적 납입보험료를 넘는 상태"],"a":2,"e":"판매보상(수수료·시책)과 해약환급금을 합친 돈이 **낸 보험료보다 커지는** 상태예요."},{"q":"금감원의 이번 주문을 바르게 설명한 것은?","o":["규정 확대가 아니라 보험사 자체 판매비용 내부통제를 강화하라는 주문이다","연금보험 판매보상에도 1200% 룰을 공식 적용했다","연금보험의 시책 지급을 전면 금지했다"],"a":0,"e":"보장성 규제를 그대로 옮긴 게 아니라 **판매비용 내부통제**를 강화하라는 주문이에요."},{"q":"회차별 시책 환수 기준만으로 차익거래 여부를 판단할 수 없는 이유는?","o":["환수율은 회차와 상관없이 모든 연금보험에서 같기 때문","해지 시점의 해약환급금과 환수 뒤 실제 남는 판매보상을 함께 봐야 하기 때문","연금보험은 시책을 받아도 환급금과 합칠 수 없기 때문"],"a":1,"e":"**환수액을 반영한 뒤 실제로 남는 이익**과 그 시점의 해약환급금을 함께 봐야 차익 여부를 알 수 있어요.","deep":true}],"terms":[{"t":"1200% 룰","d":"보험사가 설계사에게 계약 첫해에 줄 수 있는 수수료를 월 보험료의 12배 이내로 묶는 규칙이에요."},{"t":"차익거래","d":"보험에서 수수료·시책과 해약환급금을 합친 돈이 낸 보험료보다 커서, 일찍 해지할수록 이득이 생기는 상황이에요."},{"t":"시책","d":"보험사가 판매를 늘리려고 기본 수수료 외에 설계사나 대리점에 추가로 주는 보상이에요."},{"t":"해약환급금","d":"계약자가 보험을 중간에 해지할 때 돌려받는 돈이에요."},{"t":"수수료 환수","d":"계약이 일찍 해지되면 이미 지급한 모집수수료를 다시 돌려받는 것이에요."}],"thread":{"id":"sales-channel","name":"판매채널과 수수료"},"jobs":["상품개발","영업·채널","계리"],"sources":[{"name":"보험저널","url":"https://www.insjournal.co.kr/news/articleView.html?idxno=33428"}],"brief":{"what":"금감원이 1200% 룰 밖에 있는 연금보험에도 보험사가 스스로 차익거래 방지 관리 체계를 만들라고 주문한 것으로 알려졌어요.","why":"700종신 판매가 위축되자 1200% 룰을 적용받지 않는 연금보험이 대체 상품으로 떠올라서, 판매가 규제 밖으로 쏠리는 일을 미리 막으려는 거예요.","so":"보험사는 모집수수료·시책·해약환급금을 누적 납입보험료와 계약별·회차별로 비교해야 하고, 상품개발과 계리는 **어느 회차에서도 합계가 납입보험료를 넘지 않게** 설계해야 해요."},"pre":["차익거래","1200% 룰"]},{"id":"2026-11-04-8","date":"2026-11-04","tag":"상품개발","title":"안 쓴 치료비 보장을 내년으로 넘긴다? 흥국화재 '한도이연형'이 6개월 독점권을 받은 이유","predict":{"q":"흥국화재의 한도이연형 담보는 치료마다 연 1회씩 따로 보장하는 담보와 비교하면 보험료가 어떨까요?","options":["약 12~20% 싸다","약 28~47% 비싸다","약 28~47% 싸다"],"answer":2,"reveal":"회사 설명으로는 치료별 연 1회형보다 **약 28~47% 저렴**해요(상품과 담보 조건에 따라 달라요). 보장 횟수를 늘린 게 아니라, 안 쓴 한도를 다음 해로 넘기는 방식으로 보장 구조를 바꿨기 때문이에요."},"comic":{"title":"올해 못 쓴 한 번, 내년에 쓰기","panels":[{"caption":"암 주요 치료를 연 1회 보장하는 보험","bg":"hospital","chars":[{"who":"carrot","mood":"worried","pose":"doc","say":"올해는 치료를 안 받았는데…"}]},{"caption":"치료가 한 해에 몰리면 문제예요","bg":"home","chars":[{"who":"carrot","mood":"sad","pose":"worry","fx":"gloom","say":"내년엔 두 번 필요한데 한 번뿐?"}]},{"caption":"흥국화재가 받은 6개월 독점권","bg":"office","sign":"안 쓴 한도 이월, 최대 5회","chars":[{"who":"insurer","mood":"happy","pose":"point","fx":"sparkle","say":"안 쓴 1회는 내년으로 넘겨요"}]},{"caption":"망고 계리사의 정리","bg":"meeting","board":"flat","chars":[{"who":"mango","mood":"thinking","pose":"point","fx":"idea","say":"이월이 몰릴 때 위험률을 따져야죠"}]}]},"figs":[{"type":"compare","title":"치료비 담보 보장 방식 비교","left":"주요 치료 통합형(연 1회)","right":"한도이연형","rows":[{"label":"그해 치료를 안 받으면","left":"그해 한도가 사라져요","right":"다음 해로 넘어가요(최대 5회)"},{"label":"치료가 몰린 해","left":"연 1회뿐이라 부족할 수 있어요","right":"이월분을 더해 최대 연 2회"},{"label":"보험료(치료별 연 1회형 대비)","left":"저렴한 편","right":"약 28~47% 낮음(회사 설명)"}],"note":"치료별 연 1회형은 보장 범위가 넓지만 보험료가 비싸요. SBS Biz·토요경제 2026년 10월 15일 기사 기준이에요.","look":"안 쓴 한도가 통합형은 사라지고, 한도이연형은 최대 5회까지 넘어가요."},{"type":"timeline","title":"한도이연형이 독점권을 얻기까지","items":[{"when":"2026년 9월","label":"흥국화재, 배타적사용권 신청 사실 알려짐"},{"when":"2026년 10월 15일","label":"손해보험협회, 6개월 배타적사용권 부여","now":true},{"when":"2027년 4월 7일","label":"독점 기간 끝, 다른 손보사도 판매 가능"}],"look":"6개월 독점이 2027년 4월 7일에 끝나고 그 뒤엔 다른 손보사도 팔 수 있어요."}],"numbers":[{"label":"배타적사용권","value":"6개월","note":"2027년 4월 7일까지 독점"},{"label":"한도 이연","value":"최대 5회","note":"처음 진단받은 때부터 적용"},{"label":"보험료 차이","value":"28~47%↓","note":"치료별 연 1회형과 비교(회사 설명)"}],"points":["흥국화재가 손해보험협회에서 **'한도이연형 구조'**로 6개월 배타적사용권을 받았어요. 보장 질병을 처음 진단받은 뒤 그해 쓰지 않은 연간 보장한도를 다음 해로 넘길 수 있고, 이월은 최대 5회까지 돼요.","예를 들어 암 주요 치료를 묶어 연 1회 보장하는 담보는 치료를 안 받으면 그해 한도가 사라지지만, 한도이연형은 안 쓴 1회가 넘어가 **다음 해 최대 2회**까지 보장받을 수 있어요.","회사는 보장 횟수를 일괄로 늘린 게 아니라 **보장 방식을 바꾼 것**이라며, 치료별 연 1회형보다 보험료가 약 28~47% 싸다고 설명했어요."],"why":"암 치료는 수술, 항암, 방사선이 **한 해에 몰리는 경우**가 많아요. 그래서 '싸지만 부족한 통합형'과 '넉넉하지만 비싼 치료별형' 사이에 빈틈이 있었고, 한도이연형은 그 사이를 노린 설계예요. 최근 보장한도 심의가 엄격해지면서 단순히 한도를 늘리는 상품은 독창성을 인정받기 어려워졌는데, 이 상품은 **급부 지급 방식 자체**를 바꿔서 독점권을 얻었다는 점이 눈여겨볼 만해요. 계리 관점에서는 이월된 한도가 실제로 얼마나 쓰일지, 치료가 몰리는 해에 지급이 얼마나 늘지를 경험통계로 추정하는 게 보험료를 정하는 핵심이 될 수 있어요.","chain":["암 치료가 특정 해에 몰리는 경향","통합형 연 1회는 그해 보장이 부족","치료별 연 1회형은 보험료가 비쌈","안 쓴 한도를 다음 해로 넘기는 구조 개발","6개월 배타적사용권 획득","다른 손보사는 2027년 4월 7일까지 판매 불가"],"role":{"q":"당신은 손해보험사 상품개발팀 신입이에요. 팀장님이 묻습니다. \"경쟁사 한도이연형이 보험료가 28~47%나 싸다는데, 우리도 이월 기능만 붙이면 되는 거 아냐?\" 상품을 따라 만들기 전에 따져볼 점을 설명해보세요.","model":"먼저 독점 기간이 2027년 4월 7일까지라 그 전에는 같은 구조의 담보를 팔 수 없다. 그 뒤에 비슷한 상품을 만든다면, 보험료가 싼 이유가 **이월된 한도가 모두 쓰이지는 않는다는 가정**에 있다는 점을 봐야 한다. 그래서 암 진단 뒤 해마다 수술·항암·방사선 치료가 얼마나 몰리는지, 이월이 최대 5회까지 쌓였을 때 한 해 지급이 얼마나 커질 수 있는지를 경험통계로 추정해야 한다. 이월 횟수 상한, 이월이 시작되는 시점(처음 진단 시점) 같은 조건이 위험률에 주는 영향도 시나리오로 확인한 뒤 보험료를 정하는 게 순서다."},"summary":"보통 치료비 보험은 그해 안 쓰면 보장이 그냥 사라지는데, 흥국화재가 안 쓴 걸 다음 해로 넘길 수 있게 만들어서 6개월 독점권을 받았어. 치료가 한 해에 몰리는 암 같은 병에 유리하고, 치료마다 따로 보장하는 것보다 보험료도 싸대.","interview":{"q":"흥국화재의 한도이연형 치료비 담보가 배타적사용권을 받았습니다. 상품개발 관점에서 이 상품의 의미를 어떻게 보나요?","guide":"결론부터: 보장 한도를 늘리는 대신 지급 방식을 바꿔 보장과 보험료의 균형을 찾은 좋은 사례라고 봐요.\n근거: 쓰지 않은 연간 한도를 최대 5회까지 넘길 수 있어 치료가 몰린 해에 최대 연 2회 보장되고, 보험료는 치료별 연 1회형보다 약 28~47% 낮다고 해요. 독점 기간은 6개월이에요.\n관점: 상품개발·계리에서는 이월 한도의 실제 사용률과 치료 집중도를 경험통계로 추정해 위험률을 잡는 게 핵심이에요.\n마무리: 보장한도 심의가 엄격해진 만큼, 앞으로는 이런 구조 혁신이 상품 경쟁의 중심이 될 거라고 정리해요."},"quiz":[{"q":"한도이연형 담보에서 그해 쓰지 않은 연간 보장한도는 어떻게 되나요?","o":["그해 안에 쓰지 않으면 환급금으로 돌려받는다","그해에 사라지고 다음 해에는 새 한도만 생긴다","다음 해로 넘어간다(최대 5회)"],"a":2,"e":"보장 질병을 처음 진단받은 뒤부터 안 쓴 한도가 **다음 해로 이연**되고, 최대 5회까지 가능해요."},{"q":"이 상품으로 흥국화재가 받은 배타적사용권 기간은?","o":["6개월","9개월","12개월"],"a":0,"e":"6개월이에요. 다른 손보사는 2027년 4월 7일까지 같은 구조의 담보를 팔 수 없어요."},{"q":"한도이연형 담보의 보험료를 정할 때 계리적으로 가장 중요한 추정은?","o":["새 담보에 가입할 사람이 얼마나 될지","이월된 한도의 실제 사용률과 치료가 몰리는 정도","치료별 연 1회형 담보의 판매량"],"a":1,"e":"보험료가 싼 이유가 이월 한도가 모두 쓰이지는 않는다는 데 있어서, **이월 사용률과 치료 집중도**를 통계로 추정하는 게 핵심이에요.","deep":true}],"terms":[{"t":"배타적사용권","d":"독창적인 보험상품을 만든 회사에 일정 기간 다른 회사가 비슷한 상품을 팔지 못하게 하는 독점 판매 권리예요. 보험업계의 특허처럼 쓰여요."},{"t":"연간 보장한도","d":"한 해 동안 보험금을 받을 수 있는 최대 횟수나 금액이에요."},{"t":"한도이연","d":"그해 쓰지 않은 보장한도를 없애지 않고 다음 해로 넘기는 방식이에요."},{"t":"담보","d":"보험상품 안에서 어떤 사고나 치료에 보험금을 줄지 정한 보장 단위예요."}],"thread":{"id":"product-competition","name":"보험상품 개발 경쟁"},"jobs":["상품개발","계리"],"companies":["흥국화재"],"sources":[{"name":"SBS Biz","url":"https://biz.sbs.co.kr/amp/article/20000340196"},{"name":"토요경제","url":"https://sateconomy.co.kr/news/view/1065584460267192"}],"brief":{"what":"흥국화재가 안 쓴 연간 보장한도를 다음 해로 넘기는 한도이연형 구조로 손해보험협회에서 6개월 배타적사용권을 받았어요.","why":"암 치료는 수술·항암·방사선이 한 해에 몰리는 경우가 많은데, 싸지만 부족한 통합형과 넉넉하지만 비싼 치료별형 사이에 빈틈이 있었어요.","so":"치료를 안 받은 해의 한도 1회가 넘어가 다음 해 최대 2회까지 보장받을 수 있고, 회사 설명으로는 **치료별 연 1회형보다 약 28~47% 저렴**해요. 다른 손보사는 2027년 4월 7일까지 같은 구조를 팔 수 없어요."},"pre":["배타적사용권","한도이연"]},{"id":"2026-11-04-9","date":"2026-11-04","tag":"건전성·자본","title":"1조 원을 갚을 날이 다가온다, 한화생명이 최대 8,000억 원 자본확충에 나선 이유","predict":{"q":"한화생명의 상반기 말 지급여력비율(킥스)은 167%로 권고치 130%를 넘어요. 그런데도 최대 8,000억 원 자본확충을 추진하는 가장 큰 이유는?","options":["후순위채로 기본자본을 늘려 내년 규제를 미리 맞추려고","보험금 지급이 급격히 늘어 자본이 빠르게 줄고 있어서","갚을 후순위채와 계열사 투자로 앞으로 비율이 떨어질 수 있어서"],"answer":2,"reveal":"2022년에 낸 약 1조 원 규모 후순위채를 **내년 2월부터 조기상환**해야 하고, 애큐온캐피탈 인수(4,400억 원)와 한화투자증권 증자(2,500억 원)에 약 7,000억 원이 들어가요. 그래서 앞으로 **비율이 떨어질 것에 대비**하는 거예요."},"figs":[{"type":"bars","title":"한화생명이 마주한 돈 들어갈 곳과 이번 확충 규모","unit":"억 원","items":[{"label":"2022년 후순위채 조기상환","value":10000,"text":"약 1조 원"},{"label":"애큐온캐피탈 인수","value":4400,"text":"4,400억 원"},{"label":"한화투자증권 유상증자","value":2500,"text":"2,500억 원"},{"label":"이번 자본확충(최대)","value":8000,"text":"최대 8,000억 원","hi":true}],"note":"후순위채는 7억 5,000만 달러(약 1조 원)예요. 풋옵션이 행사되면 애큐온 관련 4,300억 원이 더 들 수 있어요. 서울경제 2026년 10월 15일 기사 기준이에요.","look":"후순위채 상환 약 1조 원에 애큐온 인수 4,400억 원 등이 겹쳐요."},{"type":"timeline","title":"한화생명 자본 일정","items":[{"when":"2022년","label":"해외에서 10년 만기 후순위채 7억 5,000만 달러 발행"},{"when":"2026년 9월 30일","label":"애큐온캐피탈 인수 계약(4,400억 원)"},{"when":"2026년 10월 15일","label":"최대 8,000억 원 자본확충 추진, 주관사 선정 착수","now":true},{"when":"2026년 11월","label":"수요예측과 납입 마칠 계획"},{"when":"2027년 2월","label":"기존 후순위채 조기상환 시작"}],"look":"11월에 수요예측과 납입을 마치고 2027년 2월부터 조기상환을 시작해요."}],"numbers":[{"label":"자본확충 규모","value":"최대 8,000억 원","note":"후순위채 발행이 유력"},{"label":"상반기 말 킥스","value":"167%","note":"당국 권고치 130%"},{"label":"곧 갚을 후순위채","value":"약 1조 원","note":"내년 2월부터 조기상환"},{"label":"계열사 투자","value":"약 7,000억 원","note":"애큐온 인수·한화투자증권 증자"}],"points":["한화생명이 **최대 8,000억 원** 규모의 자본성 증권 발행을 추진하고, 후순위채가 유력하다고 알려졌어요. 국내 증권사에 주관사 제안 요청서를 보냈고 11월 안에 수요예측과 납입을 마칠 계획이에요.","2022년에 해외에서 낸 7억 5,000만 달러(약 1조 원) 후순위채를 **내년 2월부터 조기상환**해야 하고, 애큐온캐피탈 인수와 한화투자증권 유상증자에도 약 7,000억 원이 들어가요.","상반기 말 지급여력비율(킥스)은 167%로 권고치 130%를 넘지만, 큰돈이 빠져나가면 **비율이 떨어질 수 있어** 미리 자본을 채우는 거예요. 후순위채를 내려면 금감원 승인이 필요해요."],"why":"보험사 후순위채는 일정 기간이 지나면 회사가 먼저 갚는 **조기상환(콜옵션)**을 염두에 두고 발행하는 경우가 많아요. 갚으면 그만큼 보완자본이 줄어드니 새 채권으로 갈아타야 비율을 지킬 수 있어요. 여기에 한화생명은 캐피탈·증권 같은 계열사에 돈을 넣고 있어서, **본업 밖 투자가 자본 여력을 얼마나 쓰는지**가 함께 드러나요. 후순위채는 기본자본이 아니라 보완자본이라는 점도 중요해요. 내년부터 기본자본 지급여력비율 규제가 시작되기 때문에, 빚 성격의 자본으로 전체 비율을 지키는 방식에는 한계가 있다는 걸 함께 생각해보세요.","chain":["2022년 약 1조 원 후순위채 발행","내년 2월부터 조기상환 부담","애큐온 인수·증권 증자에 약 7,000억 원","지급여력비율(킥스) 하락 우려","최대 8,000억 원 후순위채 발행 추진","금감원 승인과 11월 수요예측"],"role":{"q":"당신은 생명보험사 리스크관리팀 신입이에요. 재무팀장님이 묻습니다. \"킥스가 167%나 되는데 왜 금감원에 비율이 130% 밑으로 갈 수 있다는 시나리오까지 내야 하죠?\" 이유와 준비할 일을 설명해보세요.","model":"후순위채는 갚기로 한 빚이라 보험사가 마음대로 늘리면 자본의 질이 떨어질 수 있다. 그래서 금감원은 발행을 승인할 때 **앞으로 1년 동안 비율이 130%를 밑돌 위험이 있는지** 시나리오 분석으로 확인한다. 우리 회사는 내년 2월부터 약 1조 원 후순위채를 조기상환해야 하고, 애큐온 인수와 증권 증자로 약 7,000억 원이 빠져나가며, 풋옵션이 행사되면 4,300억 원이 더 들 수 있다. 리스크관리팀은 이 자금 유출과 금리·주가 충격을 함께 넣어 **비율이 어디까지 내려갈 수 있는지** 계산하고, 새 후순위채가 들어왔을 때 회복 정도를 보여줘야 한다. 동시에 내년 기본자본 규제에는 후순위채가 도움이 안 된다는 점도 보고해야 한다."},"summary":"한화생명이 예전에 빌린 1조 원을 내년부터 먼저 갚아야 하고 계열사에도 돈을 많이 넣어서, 건전성 비율이 떨어질까 봐 최대 8,000억 원을 새로 빌려 자본을 채우려는 거야.","interview":{"q":"한화생명이 후순위채로 최대 8,000억 원 자본확충을 추진합니다. 한화생명 입장에서 이 결정의 의미와 한계를 어떻게 보나요?","guide":"결론부터: 조기상환과 계열사 투자로 생길 비율 하락을 미리 막는 합리적인 선택이지만, 자본의 질을 높이는 근본 대책은 아니라고 봐요.\n근거: 내년 2월부터 약 1조 원 후순위채를 갚아야 하고, 애큐온 인수 4,400억 원과 증권 증자 2,500억 원이 들어가요. 상반기 말 킥스는 167%예요.\n관점: 리스크관리·계리 관점에서는 후순위채가 보완자본이라 기본자본 비율 규제에는 도움이 안 되고, 이자 비용도 생긴다는 점을 짚어요.\n마무리: 길게는 보험계약마진이 큰 상품으로 이익잉여금을 쌓아 기본자본을 키우는 게 답이라고 정리해요."},"quiz":[{"q":"한화생명이 내년 2월부터 조기상환해야 하는 기존 후순위채 규모는?","o":["약 7,000억 원","약 8,000억 원","약 1조 원"],"a":2,"e":"2022년 해외 기관을 대상으로 낸 7억 5,000만 달러, **약 1조 원**이에요."},{"q":"후순위채는 지급여력비율 계산에서 어떤 자본으로 인정되나요?","o":["보완자본","기본자본","지급여력비율 계산에서 빼는 부채"],"a":0,"e":"후순위채는 **보완자본**이에요. 그래서 기본자본만 보는 비율 규제에는 도움이 되지 않아요."},{"q":"보험사가 후순위채를 발행하려 할 때 금감원 승인을 받으려면 무엇을 내야 하나요?","o":["앞으로 3년간 배당을 줄이겠다는 계획","앞으로 1년간 비율이 130%를 밑돌 수 있다는 시나리오 분석","앞으로 1년간 비율이 130%를 웃돈다는 시나리오 분석"],"a":1,"e":"기사에 따르면 **향후 1년간 비율이 130%를 밑돌 것이라는 시나리오 분석**을 제출해야 해요.","deep":true}],"terms":[{"t":"후순위채","d":"회사가 망하면 다른 빚보다 늦게 갚는 채권이에요. 보험사가 보완자본을 늘리려고 많이 발행해요."},{"t":"보완자본","d":"손실을 막는 데 일부 제한이 있는 자본이에요. 후순위채 같은 자본증권이 대표적이에요."},{"t":"조기상환권","d":"만기 전에 발행한 회사가 채권을 먼저 갚을 수 있는 권리예요. 콜옵션이라고도 불러요."},{"t":"지급여력비율","d":"보험사가 위험이 닥쳐도 보험금을 줄 수 있는 능력을 보여주는 건전성 지표예요. 지금 제도의 이름을 따 킥스 비율이라고도 불러요."},{"t":"수요예측","d":"채권이나 주식을 팔기 전에 기관투자자에게 얼마에 얼마나 살지 미리 물어보는 절차예요."}],"thread":{"id":"kics","name":"지급여력제도(킥스)"},"jobs":["리스크관리","계리"],"companies":["한화생명"],"sources":[{"name":"서울경제","url":"https://m.sedaily.com/article/20102075"}],"brief":{"what":"한화생명이 최대 8,000억 원 규모의 자본성 증권 발행을 추진하고 있고, 후순위채가 유력하다고 알려졌어요.","why":"2022년에 낸 약 1조 원 후순위채를 내년 2월부터 조기상환해야 하고, 애큐온캐피탈 인수와 한화투자증권 유상증자에도 약 7,000억 원이 들기 때문이에요.","so":"상반기 말 지급여력비율(킥스)은 167%로 권고치 130%를 넘지만 **비율이 떨어질 것에 대비**한 거예요. 후순위채는 보완자본이라 내년부터 시작되는 기본자본 규제에는 도움이 되지 않아요."},"pre":["후순위채","보완자본"]},{"id":"2026-11-04-10","date":"2026-11-04","tag":"건전성·자본","title":"보험료를 못 내 멈춘 생명보험 104조 원, ABL생명은 1년 새 두 배 가까이","predict":{"q":"22개 생명보험사의 효력상실·해약 계약 잔액은 1년 전보다 어떻게 변했을까요?","options":["5조 원 넘게 줄었다","5조 원 넘게 늘었다","1조 원 안팎으로 소폭 늘었다"],"answer":1,"reveal":"2분기 누계 기준 **104조 6,515억 원**으로 1년 새 5조 5,342억 원(5.58%) 늘었어요. 22곳 중 14곳이 늘었고, ABL생명은 92.7% 늘어 증가율과 증가액 모두 1위였어요."},"comic":{"title":"멈춘 보험의 값","panels":[{"caption":"금리가 오르고 생활비 부담이 커지자","bg":"home","chars":[{"who":"potato","mood":"worried","pose":"phone","say":"대출 이자도 올랐는데 보험료까지…"}]},{"caption":"보험료를 못 내 계약이 멈췄어요","bg":"night","sign":"효력상실·해약 104조 원","chars":[{"who":"potato","mood":"sad","pose":"shrug","fx":"gloom","say":"일단 보험부터 끊자"}]},{"caption":"보험사도 미래 이익이 줄어요","bg":"office","board":"down","chars":[{"who":"insurer","mood":"surprised","pose":"worry","fx":"exclaim","say":"1년 새 5조 원 넘게 늘었다고?"}]},{"caption":"망고 계리사의 정리","bg":"meeting","chars":[{"who":"mango","mood":"thinking","pose":"doc","fx":"idea","say":"해지율 가정과 부활 안내를 함께 봐요"}]}]},"figs":[{"type":"bars","title":"효력상실·해약 계약 잔액 1년 증감률(2분기 누계)","unit":"%","items":[{"label":"ABL생명","value":92.7,"text":"+92.7%","hi":true},{"label":"미래에셋생명","value":14.7,"text":"+14.7%"},{"label":"교보생명","value":13,"text":"+13.0%"},{"label":"흥국생명","value":11.1,"text":"+11.1%"},{"label":"삼성생명","value":6.2,"text":"+6.2%"},{"label":"한화생명","value":-4.1,"text":"−4.1%"},{"label":"신한라이프","value":-6,"text":"−6.0%"},{"label":"동양생명","value":-6.4,"text":"−6.4%"}],"note":"생명보험협회 공시를 정리한 CEO스코어데일리 2026년 10월 18일 기사 기준이에요.","look":"ABL생명이 +92.7%로 가장 가팔랐고, 한화생명 등 일부는 줄었어요."},{"type":"bars","title":"잔액이 가장 큰 3곳","unit":"조 원","items":[{"label":"삼성생명","value":22.4,"text":"22조 3,971억 원"},{"label":"교보생명","value":14.3,"text":"14조 3,288억 원"},{"label":"한화생명","value":11.2,"text":"11조 1,540억 원"}],"note":"막대 길이는 조 원 단위 어림값이에요. 세 곳 합계가 업계 전체의 45.8%예요.","look":"삼성생명 22조 3,971억 원 등 세 곳이 업계의 45.8%예요."}],"numbers":[{"label":"업계 잔액","value":"104조 6,515억 원","note":"22개 생보사, 2분기 누계"},{"label":"1년 증가","value":"+5조 5,342억 원","note":"+5.58%"},{"label":"ABL생명 증가율","value":"+92.7%","note":"1조 9,422억 → 3조 7,421억 원"},{"label":"증가한 회사","value":"14곳","note":"22곳 중, 8곳은 감소"}],"points":["보험료를 못 내 효력이 멈추거나 중간에 해지된 생명보험 계약의 잔액이 **104조 6,515억 원**으로 1년 새 5조 5,342억 원(5.58%) 늘었어요.","ABL생명이 1조 9,422억 원에서 3조 7,421억 원으로 **92.7%** 늘어 가장 가팔랐고, 교보생명(+13.0%), 삼성생명(+6.2%)도 늘었어요. 반대로 한화생명, 신한라이프, 동양생명은 줄었어요.","기준금리가 7월과 8월 두 번 올라 연 3.00%가 됐고, 은행 부실채권비율도 0.63%로 높아졌어요. **가계 형편이 어려워질수록** 보험부터 끊는 흐름이 숫자로 보이는 거예요."],"why":"계약이 중간에 멈추면 보험사가 앞으로 나눠 받을 이익인 **보험계약마진이 사라져요**. 그래서 해지가 예상보다 많으면 이익 전망이 바로 흔들리고, 해지율은 계리사가 보험료와 보험부채를 계산할 때 쓰는 핵심 가정이에요. 보험연구원은 실업률, 시장금리, 물가가 오르면 해약률이 높아진다고 분석했어요. 소비자 쪽에서도 문제가 커요. 보험료가 부담돼 해지한 사람의 97.6%가 보장성보험을 끊었다는 조사가 있어서, **아플 때 보장이 없는 공백**이 생길 수 있어요. 뉴스를 볼 때 금리와 가계 부채 소식이 보험 해지율로 이어지는지 함께 읽어보세요.","chain":["기준금리 인상과 가계 부실 증가","보험료 납입 부담 커짐","효력상실·해약 계약 104조 원으로 증가","보험계약마진 감소, 이익 전망 흔들림","소비자 보장공백 우려","부활 안내·납입유예 등 유지 관리 필요"],"role":{"q":"당신은 생명보험사 계리팀 신입이에요. 팀장님이 묻습니다. \"우리 효력상실·해약 잔액이 1년 새 크게 늘었어. 결산 전에 무엇부터 점검해야 할까?\" 점검할 것과 회사가 할 일을 설명해보세요.","model":"먼저 실제 해지가 **해지율 가정보다 얼마나 많았는지** 상품별, 경과 기간별로 비교해야 한다. 차이가 크면 가정을 바꿔야 하고, 그만큼 보험계약마진과 보험부채가 달라진다. 이번처럼 금리 인상과 가계 부실이 겹친 시기의 해지는 일시적인지 추세인지도 나눠 봐야 한다. 회사 차원에서는 업계 관계자 말처럼 **계약이 멈춘 이유를 유형별로 관리**하고, 효력이 멈춘 계약에는 부활 안내를, 납입이 어려운 고객에게는 납입유예 같은 지원을 안내해 계약을 지키는 것이 이익과 소비자 보호에 모두 도움이 된다."},"summary":"보험료를 못 내서 멈추거나 해지된 생명보험이 104조 원어치나 되고 1년 새 5조 원 넘게 늘었어. 금리가 오르고 살림이 빠듯해지니까 보험부터 끊는 거라, 보험사는 미래 이익이 줄고 사람들은 보장이 비는 문제가 생겨.","interview":{"q":"생명보험사의 효력상실·해약 계약이 1년 새 5조 원 넘게 늘었습니다. 계리 관점에서 어떤 위험으로 보고, 회사는 어떻게 대응해야 할까요?","guide":"결론부터: 해지 증가는 미래 이익과 가정의 정확성을 동시에 흔드는 위험이라, 가정 점검과 계약 유지 관리를 함께 해야 한다고 봐요.\n근거: 22개 생보사 잔액이 104조 6,515억 원으로 5.58% 늘었고, ABL생명은 92.7% 늘었어요. 기준금리 인상과 부실채권비율 상승이 겹쳤어요.\n관점: 계리에서는 실제 해지와 해지율 가정의 차이를 상품·경과 기간별로 보고, 보험계약마진에 주는 영향을 계산해요.\n마무리: 부활 안내와 납입유예로 계약을 지키는 게 회사 이익과 소비자 보장을 함께 지키는 길이라고 정리해요."},"quiz":[{"q":"22개 생보사의 효력상실·해약 계약 잔액은 2분기 누계 기준 얼마인가요?","o":["약 99조 원","약 110조 원","약 104조 원"],"a":2,"e":"**104조 6,515억 원**이에요. 1년 전 99조 1,173억 원보다 5조 5,342억 원 늘었어요."},{"q":"증가율과 증가액 모두 1위인 회사는?","o":["ABL생명","삼성생명","미래에셋생명"],"a":0,"e":"ABL생명이 1조 9,422억 원에서 3조 7,421억 원으로 **92.7%** 늘었어요."},{"q":"해지가 예상보다 많아지면 새 국제회계기준에서 보험사에 생기는 일은?","o":["보험계약마진은 그대로이고 해지율 가정만 바뀐다","보험계약마진이 줄어 미래 이익 전망이 낮아진다","보험계약마진이 늘어 미래 이익 전망이 높아진다"],"a":1,"e":"계약이 사라지면 앞으로 나눠 받을 이익인 **보험계약마진도 사라져요**. 그래서 해지율 가정이 중요해요.","deep":true}],"terms":[{"t":"효력상실","d":"보험료를 정해진 기간 안에 내지 않아 보험계약의 효력이 멈춘 상태예요."},{"t":"해지율","d":"보험계약이 일정 기간 안에 중도 해지되는 비율이에요. 보험료와 보험부채 계산의 핵심 가정이에요."},{"t":"보험계약마진","d":"보험계약에서 앞으로 나눠서 이익으로 인식할, 아직 실현되지 않은 이익이에요."},{"t":"부활","d":"효력이 멈춘 보험계약을 밀린 보험료를 내고 다시 살리는 제도예요."},{"t":"보장공백","d":"보험을 해지하거나 효력이 멈춰 아프거나 사고가 나도 보장을 받지 못하는 상태예요."}],"thread":{"id":"rates","name":"금리와 보험료"},"jobs":["계리","리스크관리"],"companies":["ABL생명","교보생명","삼성생명","한화생명","미래에셋생명","흥국생명","신한라이프","동양생명"],"sources":[{"name":"CEO스코어데일리","url":"https://m.ceoscoredaily.com/page/view/2026101314402939639"}],"brief":{"what":"22개 생명보험사의 효력상실·해약 계약 잔액이 2분기 누계 기준 104조 6,515억 원으로, 1년 새 5조 5,342억 원(5.58%) 늘었어요.","why":"기준금리가 7월과 8월 두 번 올라 연 3.00%가 되고 은행 부실채권비율도 0.63%로 높아지는 등, 가계 형편이 어려워질수록 보험부터 끊는 흐름이 나타났어요.","so":"계약이 멈추면 앞으로 나눠 받을 이익인 **보험계약마진이 사라져** 이익 전망이 흔들리고, 소비자는 아플 때 보장이 없는 공백이 생길 수 있어요."},"pre":["효력상실","해지율"]},{"id":"2026-11-04-11","date":"2026-11-04","tag":"건전성·자본","title":"생보사 이익잉여금 63조 원, 그런데 절반 가까이는 배당도 못 하는 돈?","predict":{"q":"생명보험사 이익잉여금이 1년 새 4조 원 넘게 늘었어요. 그런데 지난해 주주배당을 한 상장 생보사는 몇 곳일까요?","options":["3곳","1곳","2곳"],"answer":1,"reveal":"**삼성생명 1곳**뿐이에요. 2021년에는 3곳이었어요. 이익잉여금 안에 배당 재원에서 빠지는 **해약환급금준비금**이 많이 들어 있어서, 총액이 커져도 쓸 수 있는 돈은 많지 않아요."},"comic":{"title":"통장은 두둑한데 왜 못 써?","panels":[{"caption":"생보사 이익잉여금이 63조 원에 육박","bg":"office","board":"up","chars":[{"who":"insurer","mood":"happy","pose":"cheer","fx":"sparkle","say":"1년 새 4조 원이나 늘었어!"}]},{"caption":"주주가 묻습니다","bg":"meeting","chars":[{"who":"onion","mood":"surprised","pose":"point","fx":"question","say":"그럼 배당은 언제 줘요?"},{"who":"insurer","mood":"worried","pose":"shrug"}]},{"caption":"절반 가까이가 해약환급금준비금이에요","bg":"focus","sign":"준비금 비중 생보 47%","chars":[{"who":"insurer","mood":"sad","pose":"worry","fx":"gloom","say":"묶여 있어서 못 꺼내요"}]},{"caption":"망고 계리사의 정리","bg":"meeting","board":"flat","chars":[{"who":"mango","mood":"thinking","pose":"doc","fx":"idea","say":"총액보다 구성을 봐야 해요"}]}]},"figs":[{"type":"bars","title":"이익잉여금 가운데 해약환급금준비금 비중","unit":"%","items":[{"label":"삼성생명","value":6,"text":"6%"},{"label":"미래에셋생명","value":59,"text":"59%"},{"label":"동양생명","value":69,"text":"69%"},{"label":"한화생명","value":92,"text":"92%","hi":true}],"note":"업계 평균은 생보사 47%, 손보사 45%예요. CEO스코어데일리 2026년 10월 18일 기사 기준이에요.","look":"한화생명 92%, 동양생명 69%인데 삼성생명은 6%로 차이가 커요."},{"type":"bars","title":"2026년 상반기 생보사 이익, 어디서 벌었나","unit":"억 원","items":[{"label":"보험손익(−26.2%)","value":19297,"text":"1조 9,297억 원"},{"label":"투자손익(+51.6%)","value":26803,"text":"2조 6,803억 원"},{"label":"당기순이익(+17.7%)","value":39254,"text":"3조 9,254억 원","hi":true}],"note":"괄호는 1년 전보다 늘거나 준 비율이에요.","look":"보험손익은 26.2% 줄고 투자손익은 51.6% 늘어 순이익을 메웠어요."}],"numbers":[{"label":"생보사 이익잉여금","value":"62조 8,991억 원","note":"6월 말, 1년 새 +7.0%"},{"label":"삼성생명","value":"16조 3,100억 원","note":"업계 증가분의 42.5%"},{"label":"흥국생명 증가율","value":"+59.2%","note":"업계에서 가장 가팔라요"},{"label":"기본자본비율","value":"148.0%→111.8%","note":"경과조치 전, 2023→2025년"}],"points":["22개 생보사의 6월 말 이익잉여금은 **62조 8,991억 원**으로 1년 새 4조 1,100억 원(7.0%) 늘었어요. 삼성생명이 16조 3,100억 원으로 규모와 증가액 모두 1위였고, 업계 증가분의 42.5%를 차지했어요.","하지만 이익잉여금 가운데 생보사 평균 47%는 배당 재원에서 빠지는 **해약환급금준비금**이에요. 삼성생명은 6%지만 한화생명은 92%, 동양생명은 69%라서, 지난해 배당한 상장 생보사는 삼성생명 1곳뿐이었어요.","상반기 순이익은 늘었지만 보험손익은 26.2% 줄고 **투자손익이 51.6% 늘어** 메운 구조였어요. 경과조치 전 기본자본비율도 2023년 148.0%에서 2025년 111.8%로 떨어졌어요."],"why":"이익잉여금은 회사가 그동안 번 이익을 쌓아둔 돈이라 **기본자본의 핵심**이에요. 그런데 새 회계기준 아래에서 시가로 잰 보험부채가 해약환급금보다 작으면 그 차이를 해약환급금준비금으로 쌓아야 해서, 총액이 커져도 배당이나 투자에 쓸 수 있는 돈은 제한돼요. 내년부터 기본자본 지급여력비율 규제(50% 미달 시 경영개선권고)가 시작되는 만큼, 업계 관계자 말처럼 **이익잉여금의 규모보다 구성**이 중요해졌어요. 계리·상품개발 관점에서는 보험손익이 줄고 투자손익에 기대는 이익 구조가 오래 갈 수 있는지, 그리고 상품 구조가 해약환급금준비금을 얼마나 늘리는지를 함께 보는 습관이 필요해요.","chain":["생보사 이익 쌓이며 이익잉여금 63조 원 육박","절반 가까이가 해약환급금준비금","배당·자본 활용 가능한 돈은 제한","보험손익 감소, 투자손익에 기댄 이익","기본자본비율 하락 추세","내년 기본자본 지급여력비율 규제 시작"],"role":{"q":"당신은 생명보험사 재무·계리 협업팀 신입이에요. 상무님이 묻습니다. \"우리 이익잉여금이 사상 최대인데, 주주들이 왜 배당을 못 하냐고 따져. 어떻게 설명하지?\" 설명과 앞으로의 방향을 정리해보세요.","model":"이익잉여금이 늘어도 그 안의 해약환급금준비금은 **법으로 쌓아야 하는 준비금이라 배당 재원에서 빠진다**. 시가로 잰 보험부채가 계약자에게 돌려줄 해약환급금보다 작을 때 차이를 쌓는 돈이라, 해약환급금 비중이 큰 상품이 많을수록 커진다. 그래서 회사별 비중이 삼성생명 6%, 한화생명 92%처럼 크게 다르다. 앞으로는 해약환급금준비금 제도 개선 논의를 지켜보는 한편, 보험손익이 26.2% 줄고 투자손익에 기댄 이익 구조를 바꾸기 위해 **보험계약마진이 큰 보장성 상품**을 늘리고, 상품 설계 단계에서 준비금 부담을 미리 계산하는 것이 방향이다."},"summary":"생보사들이 쌓아둔 이익이 63조 원 가까이 되는데, 그중 절반 가까이는 법 때문에 묶어둬야 하는 준비금이라 배당도 못 하고 자본으로 쓰기도 어려워. 그래서 작년에 배당한 상장 생보사는 삼성생명뿐이었어.","interview":{"q":"생보사 이익잉여금이 63조 원에 육박하지만 배당하는 회사는 적습니다. 이유와 보험사가 해야 할 일을 설명해보세요.","guide":"결론부터: 이익잉여금의 절반 가까이가 배당 재원에서 빠지는 해약환급금준비금이라서, 총액보다 구성을 봐야 한다고 말해요.\n근거: 6월 말 이익잉여금은 62조 8,991억 원이지만 준비금 비중이 생보 평균 47%, 한화생명은 92%예요. 지난해 배당한 상장 생보사는 삼성생명 1곳이었어요.\n관점: 상품개발·계리 관점에서 해약환급금 구조가 준비금을 키우고, 보험손익이 줄어 투자손익에 기대는 이익 구조도 지속 가능성을 따져봐야 해요.\n마무리: 보험계약마진이 큰 보장성 상품으로 본업 이익을 키워야 기본자본과 배당 여력이 함께 커진다고 정리해요."},"quiz":[{"q":"6월 말 22개 생보사의 이익잉여금 합계는?","o":["약 63조 원","약 59조 원","약 67조 원"],"a":0,"e":"**62조 8,991억 원**으로 1년 새 7.0% 늘었어요."},{"q":"이익잉여금 가운데 해약환급금준비금 비중이 가장 높다고 소개된 회사는?","o":["미래에셋생명(59%)","한화생명(92%)","동양생명(69%)"],"a":1,"e":"한화생명은 **92%**예요. 그래서 이익잉여금이 있어도 배당 재원은 많지 않아요."},{"q":"올해 상반기 생보사 순이익이 늘어난 주된 이유는?","o":["보험손익이 크게 늘어서","보험손익과 투자손익이 함께 늘어서","투자손익이 크게 늘어서"],"a":2,"e":"보험손익은 26.2% 줄었지만 **투자손익이 51.6% 늘어** 순이익이 17.7% 늘었어요.","deep":true}],"terms":[{"t":"이익잉여금","d":"회사가 벌어들인 이익 가운데 배당하지 않고 회사 안에 쌓아둔 돈이에요."},{"t":"해약환급금준비금","d":"시가로 잰 보험부채가 계약자에게 돌려줄 해약환급금보다 적을 때, 그 차이만큼 따로 쌓는 법정준비금이에요."},{"t":"기본자본","d":"손실을 막는 힘이 가장 강한 자본이에요. 자본금과 이익잉여금 등이 들어가요."},{"t":"투자손익","d":"받은 보험료를 채권, 주식 등으로 굴려서 번 이익이에요. 금리와 시장 상황에 따라 크게 흔들려요."},{"t":"보험손익","d":"보험 영업에서 남긴 이익이에요. 받은 보험료에 비해 보험금과 비용을 얼마나 잘 관리했는지 보여줘요."}],"thread":{"id":"kics","name":"지급여력제도(킥스)"},"jobs":["계리","리스크관리","상품개발"],"companies":["삼성생명","흥국생명","DB생명","미래에셋생명","한화생명","동양생명","교보생명","신한라이프"],"sources":[{"name":"CEO스코어데일리","url":"https://ceoscoredaily.com/page/view/2026101515181256823"}],"brief":{"what":"22개 생명보험사의 6월 말 이익잉여금은 62조 8,991억 원으로 1년 새 7.0% 늘었지만, 지난해 주주배당을 한 상장 생보사는 삼성생명 1곳뿐이었어요.","why":"이익잉여금 가운데 생보사 평균 47%가 배당 재원에서 빠지는 해약환급금준비금이라서, 총액이 커져도 쓸 수 있는 돈은 많지 않아요.","so":"내년부터 기본자본 지급여력비율 규제가 시작되어 **이익잉여금의 규모보다 구성**이 중요해졌어요. 보험손익이 줄고 투자손익이 메우는 이익 구조가 오래 갈지도 따져봐야 해요."},"pre":["이익잉여금","해약환급금준비금"]},{"id":"2026-11-04-12","date":"2026-11-04","tag":"소비자 보호","title":"나도 모르게 가입된 보험이 있다? 시민안전보험은 직접 청구해야 받아요","predict":{"q":"서울에 주민등록이 된 사람이 부산 여행 중에 사고를 당했어요. 시민안전보험 보험금은 어느 쪽 기준으로 받을까요?","options":["두 곳 중 보장이 더 큰 쪽","사고가 난 곳인 부산","주민등록 주소지인 서울"],"answer":2,"reveal":"기준은 사고가 난 곳이 아니라 **사고 당시 주민등록 주소지**예요. 서울 시민안전보험이 보장하는 사고라면 부산에서 다쳐도 받을 수 있어요. 다만 보험금은 자동으로 나오지 않아서 **보험사나 공제회에 직접 청구**해야 해요."},"comic":{"title":"자동 가입, 자동 지급은 아니에요","panels":[{"caption":"어느 날 뉴스를 보다가","bg":"home","chars":[{"who":"potato","mood":"surprised","pose":"phone","fx":"exclaim","say":"내가 보험에 가입돼 있었다고?"}]},{"caption":"보험료는 지자체가 냈어요","bg":"home","chars":[{"who":"potato","mood":"thinking","pose":"think","say":"다치면 알아서 주겠지?"},{"who":"regulator","mood":"worried","pose":"point","say":"직접 청구해야 해요!"}]},{"caption":"기한도 있어요","bg":"focus","sign":"청구 기한 3년","chars":[{"who":"potato","mood":"worried","pose":"worry","say":"작년 사고도 되나요?"},{"who":"regulator","mood":"happy","pose":"doc","say":"3년 안이면 돼요"}]},{"caption":"망고 계리사의 정리","bg":"office","board":"up","chars":[{"who":"mango","mood":"happy","pose":"point","fx":"idea","say":"청구가 늘면 손해율도 달라져요"}]}]},"numbers":[{"label":"보험금 청구 기한","value":"3년","note":"사고 발생일 등부터 소멸시효 원칙"},{"label":"화재 사망 중복 수령 예시","value":"3,500만 원","note":"광역 2,500만 원 + 기초 1,000만 원"},{"label":"주민이 내는 보험료","value":"0원","note":"지자체가 보험료를 부담"}],"points":["시민안전보험은 지자체가 보험료를 내고, 그 지역에 주민등록이 된 사람(등록외국인 포함)을 **별도 신청 없이 자동 가입**시키는 보험이에요. 이사하면 새 주소지 보험으로 자동으로 바뀌어요.","자연재난, 화재·폭발·붕괴, 대중교통 이용 중 사고를 공통으로 보장하고, 지역에 따라 스쿨존 교통사고, 농기계 사고, 개물림 사고도 보장해요. 시·도와 시·군·구 보험에 함께 가입돼 있으면 **같은 사고로 두 곳에서 받을 수도 있어요**.","보험금 청구권의 소멸시효는 원칙적으로 3년이라, 계약 기간이 끝났어도 기한이 남았으면 사고 당시 보험사에 청구할 수 있어요. 가입 내역은 재난보험24의 시민안전보험 조회에서 확인해요."],"why":"시민안전보험은 보험료를 낸 사람(지자체)과 보장받는 사람(주민)이 다르고, 보장받는 사람이 가입 사실을 잘 모르는 보험이에요. 이런 보험에서는 **사고가 나도 청구하지 않는 경우**가 생기기 쉬워요. 계리 관점에서는 실제 사고 빈도뿐 아니라 '얼마나 청구되느냐'도 손해율을 좌우해요. 안내가 늘어 청구가 많아지면 다음 해 보험료나 보장 한도 협상에도 영향을 줄 수 있어요. 이런 뉴스를 볼 땐 \"누가 내고, 누가 받고, 누가 청구하는가\"를 나눠서 생각해보세요.","chain":["지자체가 보험료를 내고 주민을 자동 가입시킴","주민 상당수는 가입 사실을 잘 모름","사고가 나도 보험금을 청구하지 않는 경우가 생김","3년 소멸시효가 지나면 받을 수 없게 됨","금감원이 직접 청구와 기한을 안내함","청구가 늘면 손해율과 다음 해 보험료가 달라질 수 있음"],"role":{"q":"당신은 손해보험사 상품개발팀 신입이에요. 한 지자체 담당자가 묻습니다. \"내년에 시민안전보험 보장 항목을 하나 더 넣고 싶은데, 보험료가 얼마나 오를지 어떻게 정하나요?\" 무엇을 따져봐야 하는지 설명해보세요.","model":"먼저 새 보장 사고가 그 지역에서 **한 해에 몇 건이나 생길지** 과거 통계로 추정해야 해요. 그다음 사고 한 건에 지급할 금액과 보장 한도를 정하고, 실제로 청구될 비율도 따져봐야 해요. 시민안전보험은 자동 가입이라 청구율이 낮을 수 있지만, 금감원 안내처럼 홍보가 늘면 **청구율이 오를 수 있어서** 보수적으로 잡는 게 안전해요. 연간 총 보상한도를 두면 보험사가 질 최대 손실을 묶을 수 있지만, 한도가 일찍 소진되면 늦게 다친 주민은 못 받을 수 있다는 점도 함께 설명해야 해요."},"summary":"동네에서 보험료를 대신 내준 시민안전보험이 있는데, 다쳐도 내가 직접 청구 안 하면 못 받고 3년 지나면 끝이야.","interview":{"q":"시민안전보험처럼 가입자가 가입 사실을 잘 모르는 단체보험에서 보험사가 신경 써야 할 점은 무엇일까요?","guide":"결론부터: 보장 내용 안내와 청구 편의성을 챙기는 동시에, 청구율 변화를 가격에 반영해야 한다고 말해요.\n근거: 시민안전보험은 주민등록만 되어 있으면 자동 가입되지만 보험금은 직접 청구해야 하고, 청구 기한은 원칙적으로 3년이에요.\n관점: 계리 관점에서 청구율은 손해율을 바꾸는 가정이라, 안내가 늘면 손해율이 오를 수 있다는 점을 짚어요.\n마무리: 보험의 신뢰는 받을 사람이 실제로 받을 때 생긴다는 점을 강조하며 마무리해요."},"quiz":[{"q":"시민안전보험의 보험료는 누가 낼까?","o":["지방자치단체가 낸다","주민이 연회비로 낸다","정부가 전액 낸다"],"a":0,"e":"지자체가 보험료를 부담하고 주민은 자동으로 가입돼요."},{"q":"시민안전보험 보험금은 어디에 청구할까?","o":["거주하는 시·군·구청","금융감독원","해당 보험회사나 공제회"],"a":2,"e":"청구처는 지자체가 아니라 그 보험을 맡은 보험회사나 공제회예요."},{"q":"자동 가입 보험의 안내가 늘어 청구가 많아질 때 계리 관점에서 가장 먼저 달라질 수 있는 것은?","o":["사업비율","손해율","지자체가 다음 해 내는 보험료"],"a":1,"deep":true,"e":"같은 사고가 나도 청구가 늘면 지급 보험금이 늘어 손해율이 오를 수 있어요."}],"terms":[{"t":"시민안전보험","d":"지자체가 보험료를 내고, 그 지역에 주민등록이 된 사람을 자동으로 가입시켜 재난과 사고를 보장하는 보험이에요."},{"t":"소멸시효","d":"권리를 일정 기간 쓰지 않으면 그 권리가 없어지는 제도예요. 보험금 청구권은 원칙적으로 3년이에요."},{"t":"연간 총 보상한도","d":"한 해 동안 보험사가 지급할 보험금의 최대 합계예요. 한도를 다 쓰면 그해 지급이 끝날 수 있어요."},{"t":"손해율","d":"보험사가 받은 보험료 가운데 보험금으로 나간 돈의 비율이에요. 높을수록 보험사 수익이 나빠져요."}],"thread":{"id":"consumer-tips","name":"보험 소비자 유의사항"},"jobs":["보상·손해사정","상품개발"],"figs":[{"type":"split","title":"화재 사망 때 중복으로 받는 예시","items":[{"label":"광역지자체(시·도) 보험","value":2500,"text":"2,500만 원"},{"label":"기초지자체(시·군·구) 보험","value":1000,"text":"1,000만 원"}],"note":"금감원이 든 예시로, 두 보험의 지급 요건을 모두 채운 경우예요. 합치면 3,500만 원이에요.","look":"화재로 숨지면 광역 2,500만 원과 기초 1,000만 원을 함께 받아요."}],"sources":[{"name":"디지털데일리","url":"https://www.ddaily.co.kr/page/view/2026110113224109561"}],"brief":{"what":"시민안전보험은 지자체가 보험료를 내 주민을 자동 가입시키지만, 보험금은 **직접 청구**해야 받을 수 있어요.","why":"주민이 가입 사실을 잘 몰라 사고가 나도 청구하지 않거나, 청구권이 3년 소멸시효를 넘기는 경우가 생기기 때문이에요.","so":"주민은 재난보험24에서 가입 내역을 확인하고 기한 안에 청구해야 하고, 청구가 늘면 손해율과 다음 해 보험료도 달라질 수 있어요."},"pre":["시민안전보험","소멸시효"]},{"id":"2026-11-04-13","date":"2026-11-04","tag":"자동차보험 · 손해율","title":"첫 차보험료가 46% 싸질 수도? 부모님 차·군 운전 경력도 인정돼요","predict":{"q":"28세 청년이 어머니 차보험에 3년 동안 무사고로 이름을 올린 뒤 본인 명의로 처음 가입하면, 보험료는 얼마나 줄까요? (아반떼, 차량가액 2,000만 원 예시)","options":["약 23%","약 46%","약 61%"],"answer":1,"reveal":"금감원 예시로 **약 61만 원, 46.1%** 줄어요. 가입경력과 무사고 경력 3년을 인정받았기 때문이에요. 다만 이런 경력 인정은 **직접 신청해야** 받을 수 있어요."},"comic":{"title":"경력은 숨어 있었다","panels":[{"caption":"첫 차를 산 날","bg":"home","chars":[{"who":"carrot","mood":"surprised","pose":"phone","fx":"sweat","say":"첫 차보험료가 왜 이렇게 비싸?"}]},{"caption":"상담을 받아보니","bg":"office","chars":[{"who":"planner","mood":"thinking","pose":"doc","say":"부모님 보험에 이름 올렸었죠?"},{"who":"carrot","mood":"surprised","fx":"question","say":"그것도 경력이에요?"}]},{"caption":"경력을 인정받으면","bg":"focus","sign":"46.1% 절감","chars":[{"who":"carrot","mood":"happy","pose":"cheer","fx":"sparkle","say":"61만 원이나 줄었다!"}]},{"caption":"망고 계리사의 정리","bg":"office","board":"down","chars":[{"who":"mango","mood":"happy","pose":"point","fx":"idea","say":"운전 경험은 위험을 재는 단서예요"}]}]},"numbers":[{"label":"부모 차보험 활용 예시","value":"−46.1%","note":"약 61만 원 절감, 경력 3년 인정"},{"label":"본인 한정·연령 한정 예시","value":"−46.2%","note":"약 114만 원 절감"},{"label":"종피보험자 경력 인정","value":"최대 3년","note":"모든 피보험자 무사고면 무사고 경력도"},{"label":"대상 청년","value":"만 19~34세","note":"청년기본법 기준"}],"points":["자동차보험료는 운전경력과 사고 이력으로 정해져서, 본인 명의 경력이 없는 청년은 보험료가 비싸요. 그런데 **부모 차보험의 종피보험자로 등록한 기간(최대 3년), 군 운전병, 장기렌터카, 관공서·법인 운전직, 해외 자동차보험 가입 경력**도 가입경력으로 인정받을 수 있어요.","가입경력은 1년 단위로 인정되고, 1년이 안 되는 경력은 합칠 수 있어요. 가입 때 신청을 놓쳤어도 보험기간 중이나 끝난 뒤 다시 신청하면 **인정된 만큼 보험료를 돌려받아요**.","금감원은 11월부터 온라인 가입 화면에 경력 인정과 할인특약 안내 팝업을 띄우고, 대면·전화 판매의 설계 화면과 상품설명 대본도 고쳐 청년층 안내가 빠지지 않게 할 계획이에요."],"why":"자동차보험료는 '이 사람이 사고를 낼 가능성'을 숫자로 바꾼 값이에요. 가입경력과 무사고 이력은 그 가능성을 가늠하는 핵심 근거라서, **같은 사람이라도 어떤 경력이 기록되느냐에 따라 보험료가 절반 가까이 달라질 수 있어요**. 상품개발 관점에서는 할인특약이 좋아도 소비자가 모르면 쓰이지 않는다는 점, 그리고 특약 조건을 어기면 보상을 못 받을 수 있다는 점까지 설계와 안내에 담아야 해요.","chain":["자동차보험료는 운전경력과 사고 이력으로 정해짐","청년은 본인 명의 경력이 없어 보험료가 높음","부모 차·군 운전 경력이 있어도 신청하지 않으면 인정 안 됨","금감원이 가입 화면과 설명 대본에 안내를 넣기로 함","경력 인정과 할인특약 이용이 늘 수 있음","청년의 첫 보험료 부담이 줄어들 수 있음"],"role":{"q":"당신은 자동차보험 상품개발팀 신입이에요. 팀장님이 묻습니다. \"군 운전병이나 부모 차 운전 경력을 가입경력으로 인정해주면, 우리 손해율에 문제가 생기지는 않을까?\" 생각을 정리해보세요.","model":"경력을 인정하는 이유는 **실제 운전 경험이 있는 사람은 처음 운전하는 사람보다 사고 위험이 낮을 것**이라고 보기 때문이에요. 그래서 먼저 경력 인정 고객과 그렇지 않은 고객의 실제 사고율을 비교해 할인 폭이 위험 차이에 맞는지 확인해야 해요. 또 병적증명서, 임대차계약서처럼 **경력을 증명하는 서류를 꼼꼼히 확인**해야 부풀려진 경력으로 할인받는 일을 막을 수 있어요. 마지막으로 운전자 한정 특약은 조건 밖의 사람이 운전하다 사고 나면 보상을 못 받을 수 있으니, 할인과 함께 그 조건을 분명히 안내해야 분쟁을 줄일 수 있어요."},"summary":"첫 차보험 비싸다고 그냥 내지 말고, 부모님 차보험에 이름 올렸던 거나 군대 운전 경력도 인정받으면 거의 절반까지 싸질 수 있어.","interview":{"q":"자동차보험에서 가입경력과 무사고 이력이 보험료에 반영되는 이유를 설명하고, 소비자 안내에서 보험사가 할 일을 말해보세요.","guide":"결론부터: 경력과 무사고 이력은 사고 위험을 가늠하는 근거라서 보험료에 반영되고, 보험사는 이를 소비자가 놓치지 않게 안내해야 한다고 말해요.\n근거: 금감원 예시에서 부모 차보험 종피보험자 경력 3년을 인정받으면 보험료가 약 46.1% 줄어요.\n관점: 상품개발 관점에서 할인 폭은 실제 사고율 차이와 맞아야 하고, 서류 확인과 특약 조건 안내가 함께 가야 한다고 덧붙여요.\n마무리: 공정한 가격은 위험을 정확히 재는 것에서 시작한다는 말로 마무리해요."},"quiz":[{"q":"부모 차보험에 종피보험자로 등록한 기간은 최대 몇 년까지 운전경력으로 인정될까?","o":["5년","2년","3년"],"a":2,"e":"종피보험자 등록 기간은 최대 3년까지 운전경력으로 인정받을 수 있어요."},{"q":"가입할 때 경력 인정 신청을 놓쳤다면?","o":["보험기간 중이나 끝난 뒤 신청해 돌려받을 수 있다","보험기간 중에만 신청할 수 있고 끝나면 받을 수 없다","다음 갱신 때 신청해야 하고 그 전 기간은 돌려받을 수 없다"],"a":0,"e":"놓쳤어도 나중에 신청하면 인정된 만큼 보험료를 돌려받을 수 있어요."},{"q":"운전자 한정 특약에 가입했을 때 꼭 알아야 할 위험은?","o":["조건 안의 사람이 사고를 내도 할인이 모두 취소된다","조건 밖의 사람이 운전하다 사고 나면 보상을 못 받을 수 있다","조건 밖의 사람이 운전하면 보험료가 즉시 두 배로 오른다"],"a":1,"deep":true,"e":"할인 대신 운전자 범위를 좁히는 특약이라, 조건에 맞지 않는 사람이 운전하면 보상이 안 될 수 있어요."}],"terms":[{"t":"가입경력 인정","d":"본인 명의가 아니어도 실제 운전한 기간을 자동차보험 가입경력으로 쳐주는 제도예요. 직접 신청해야 해요."},{"t":"종피보험자","d":"주된 피보험자 외에 같은 자동차보험으로 함께 보장받도록 이름을 올린 사람이에요."},{"t":"운전자 한정 특약","d":"운전할 수 있는 사람의 범위를 좁히는 대신 보험료를 깎아주는 특약이에요."},{"t":"할인특약","d":"정해진 조건을 지키면 보험료를 깎아주는 특약이에요. 마일리지, 대중교통 이용, 걸음 수 할인 등이 있어요."}],"thread":{"id":"auto-loss","name":"자동차보험 손해율과 보험료"},"jobs":["상품개발","언더라이팅"],"figs":[{"type":"bars","title":"청년 자동차보험료 절감 예시","unit":"만 원","items":[{"label":"부모 차보험 경력 3년 인정","value":61,"text":"약 61만 원(46.1%)"},{"label":"본인 한정·연령 한정 특약","value":114,"text":"약 114만 원(46.2%)","hi":true}],"note":"금감원이 든 예시로, 실제 보험료는 보험사마다 달라요.","look":"경력 3년 인정은 약 61만 원, 한정 특약은 약 114만 원 줄어요."}],"sources":[{"name":"시대","url":"https://www.sidae.com/article/2026110214312893452"}],"brief":{"what":"금감원이 청년의 첫 자동차보험료를 낮추는 방법을 안내했어요. 부모 차보험 경력 3년을 인정받으면 예시에서 보험료가 **46.1%** 줄어요.","why":"자동차보험료는 운전경력과 사고 이력으로 정해지는데, 본인 명의 경력이 없는 청년은 보험료가 높고 경력 인정은 직접 신청해야 하기 때문이에요.","so":"청년은 놓친 경력을 신청해 보험료를 돌려받을 수 있고, 보험사는 가입 화면과 상품설명 대본에 안내를 넣어야 해요."},"pre":["가입경력 인정","종피보험자"]},{"id":"2026-11-04-14","date":"2026-11-04","tag":"고령화·노후","title":"500조 퇴직연금에 '기금형' 문이 열린다, 한화금융 4사가 한꺼번에 움직인 이유","predict":{"q":"정부의 '퇴직연금 기능강화 방안'에 들어간 내용이 아닌 것은?","options":["퇴직연금 중도인출 사유 확대","퇴직급여 사외적립 의무화","민간 금융회사의 수탁법인 설립 허용"],"answer":0,"reveal":"정부는 오히려 **중도 인출을 퇴직연금의 약점**으로 꼽았어요. 방안의 핵심은 사외적립 의무화와 기금형 활성화, 그리고 **민간 금융회사도 인가를 받아 전문 수탁법인을 세울 수 있게** 하는 거예요."},"numbers":[{"label":"퇴직연금 적립금","value":"500조 원+","note":"기사 기준 500조 원을 넘었어요"},{"label":"함께 나선 한화 금융사","value":"4곳","note":"생명·손해보험·투자증권·자산운용"},{"label":"선포식 참석","value":"140여 명","note":"10월 30일, 여의도 63빌딩"}],"points":["정부는 퇴직연금이 양적으로는 컸지만 **도입률·가입률 정체, 중도 인출, 낮은 수익률** 때문에 노후보장 기능이 부족하다고 보고, 사외적립 의무화와 기금형 퇴직연금 활성화를 내놨어요.","한화생명, 한화손해보험, 한화투자증권, 한화자산운용은 10월 30일 '한화금융 퇴직연금 2030+ 비전 선포식'을 열고 운용 역량, 지배구조와 내부통제, 상품·디지털 경쟁력을 키우겠다고 밝혔어요.","기존 확정기여형과 개인형퇴직연금 시장 경쟁력도 함께 키우고, 영국 컨설팅 회사와 협업한 기금형 준비 과정도 공유했어요."],"why":"퇴직연금은 보험사에 **오래 머무는 큰돈**이에요. 기금형이 열리면 '어느 금융회사와 계약하느냐'보다 '누가 더 잘 운용하고 책임지느냐'의 경쟁이 될 수 있어요. 보험사는 수십 년짜리 부채를 관리하고 평생 연금을 지급해본 경험이 강점이지만, 운용 수익률에서는 증권사·자산운용사와 겨뤄야 해요. 그래서 한 그룹의 여러 금융사가 함께 움직이는 거예요. 이런 뉴스를 볼 땐 \"제도가 바뀌면 경쟁의 기준이 무엇으로 바뀌는가\"를 생각해보세요.","chain":["퇴직연금이 노후보장 기능을 충분히 못 함","정부가 사외적립 의무화와 기금형 활성화를 발표","민간 금융회사도 인가를 받아 수탁법인을 세울 수 있게 됨","운용 전문성과 지배구조가 경쟁의 핵심이 됨","한화금융 4사가 공동 비전을 선포","보험사 퇴직연금 사업의 경쟁 구도가 바뀔 수 있음"],"role":{"q":"당신은 한화생명 퇴직연금 상품팀 신입이에요. 팀장님이 묻습니다. \"기금형이 열리면 은행·증권사보다 보험사가 잘할 수 있는 게 뭘까?\" 생각을 정리해보세요.","model":"보험사의 강점은 **은퇴 뒤 돈을 나눠 주는 단계**에 있어요. 종신연금처럼 오래 사는 위험까지 맡아주는 상품은 생명보험사만 만들 수 있고, 수십 년짜리 부채와 자산을 맞추는 관리도 익숙해요. 그래서 '쌓는 단계'의 운용은 그룹의 증권·자산운용사와 함께하고, '받는 단계'는 보험사가 맡는 식으로 **생애주기 전체를 하나로 묶는 제안**이 가능해요. 다만 기금형에서는 수탁자 책임과 투명한 지배구조가 중요하다고 했으니, 계열사 상품만 담는다는 오해를 받지 않도록 내부통제도 함께 갖춰야 해요."},"summary":"회사 퇴직연금을 전문 기금이 굴리는 방식이 열리면서, 한화 금융회사 4곳이 같이 준비하겠다고 나섰어.","interview":{"q":"기금형 퇴직연금 도입이 보험사에 기회인지 위협인지 말해보세요.","guide":"결론부터: 연금 지급 단계의 강점을 살리면 기회지만, 운용 경쟁력이 없으면 위협이 될 수 있다고 말해요.\n근거: 퇴직연금 적립금은 500조 원을 넘었고, 정부는 기금형 활성화와 민간 수탁법인 설립 허용을 내놨어요. 한화금융 4사는 공동 비전을 선포했어요.\n관점: 계리·상품 관점에서는 종신연금처럼 장수 위험을 맡는 상품을 기금형과 연결하는 설계가 보험사만의 차별점이라고 덧붙여요.\n마무리: 고객의 장기적 이익을 기준으로 상품을 설계하는 역량을 키우고 싶다고 마무리해요."},"quiz":[{"q":"정부가 꼽은 퇴직연금의 약점이 아닌 것은?","o":["낮은 수익률","높은 운용 수수료","도입률과 가입률 정체"],"a":1,"e":"적립금은 500조 원을 넘을 만큼 컸지만, 도입률·가입률 정체, 중도 인출, 낮은 수익률이 약점으로 꼽혔어요. 높은 운용 수수료는 약점으로 나오지 않았어요."},{"q":"한화금융 퇴직연금 비전에 함께한 회사가 아닌 것은?","o":["한화저축은행","한화손해보험","한화자산운용"],"a":0,"e":"한화생명, 한화손해보험, 한화투자증권, 한화자산운용 4곳이 함께했어요."},{"q":"기금형 시대에 보험사가 내세울 수 있는 차별점으로 가장 알맞은 것은?","o":["증권사보다 높은 단기 운용 수익률","은행보다 많은 영업 점포망","평생 연금처럼 오래 사는 위험을 맡는 상품"],"a":2,"deep":true,"e":"장수 위험을 맡는 종신연금은 생명보험사의 고유한 강점이에요."}],"terms":[{"t":"퇴직연금","d":"회사가 근로자의 퇴직급여를 금융회사에 맡겨 쌓아두었다가, 퇴직 뒤 연금이나 일시금으로 주는 제도예요."},{"t":"기금형 퇴직연금","d":"회사 밖에 별도 기금을 두고, 전문 수탁법인이 근로자를 대신해 퇴직연금을 운용하는 방식이에요."},{"t":"사외적립","d":"퇴직급여를 회사 안이 아니라 금융회사 같은 바깥에 쌓아두는 것이에요. 회사가 어려워져도 근로자 몫을 지킬 수 있어요."},{"t":"수탁자 책임","d":"남의 돈을 맡아 굴리는 사람이 맡긴 사람의 이익을 가장 먼저 생각해야 하는 책임이에요."}],"thread":{"id":"aging","name":"고령화와 보험"},"jobs":["상품개발","리스크관리"],"companies":["한화생명","한화손해보험"],"figs":[{"type":"compare","title":"계약형과 기금형, 무엇이 다를까","left":"계약형","right":"기금형","rows":[{"label":"돈을 맡기는 방식","left":"회사가 금융회사와 계약","right":"별도 기금에 모아 맡김"},{"label":"운용하는 곳","left":"계약한 금융회사","right":"전문 수탁법인"},{"label":"경쟁의 기준","left":"어느 회사와 계약하느냐","right":"운용 성과와 지배구조"}],"note":"제도의 큰 차이를 쉽게 나눈 표예요. 구체적인 기준은 앞으로 정해질 세부안을 봐야 해요.","look":"계약형은 계약한 회사가, 기금형은 전문 수탁법인이 운용해요."}],"sources":[{"name":"허프포스트코리아","url":"https://www.huffingtonpost.kr/article/261720"}],"brief":{"what":"정부가 퇴직연금 기능강화 방안을 내놓자, 한화생명·한화손해보험·한화투자증권·한화자산운용이 10월 30일 퇴직연금 공동 비전을 선포했어요.","why":"퇴직연금 적립금이 500조 원을 넘었지만 가입률 정체, 중도 인출, 낮은 수익률로 노후보장 기능이 부족하다고 정부가 보았기 때문이에요.","so":"기금형이 열리면 경쟁의 기준이 계약 회사에서 **운용 성과와 지배구조**로 바뀔 수 있고, 보험사는 평생 연금을 맡는 강점을 살려야 해요."},"pre":["퇴직연금","기금형 퇴직연금"]},{"id":"2026-11-04-15","date":"2026-11-04","tag":"건전성·자본","title":"보험사 예금보험료 2.5~3배 인상안, 한발 물러선 수정안이 나왔다","predict":{"q":"7월 연구용역안에서 손해보험업권의 예금보험료율은 지금의 0.15%에서 몇 %로 제시됐을까요?","options":["0.54%","0.40%","0.50%"],"answer":2,"reveal":"**0.50%**였어요. 생명보험은 0.15%에서 0.40%였고요. 보험업권은 산정 근거가 불투명하다며 반발했고, 10월 30일 4차 회의에서 예금보험공사가 **인상 폭을 낮춘 수정안**을 내놨어요."},"numbers":[{"label":"손해보험 연구용역안","value":"0.50%","note":"현행 0.15%"},{"label":"생명보험 연구용역안","value":"0.40%","note":"현행 0.15%"},{"label":"예금보호한도","value":"1억 원","note":"2025년 9월 5,000만 원에서 상향"},{"label":"4차 태스크포스","value":"10월 30일","note":"인상 폭 낮춘 수정안 제시"}],"points":["2025년 9월 예금보호한도가 5,000만 원에서 1억 원으로 오르자, 예금보험기금의 손실에 대비할 재원이 필요해졌어요. 7월 연구용역안은 **은행 0.08%→0.13%, 생명보험 0.15%→0.40%, 손해보험 0.15%→0.50%**처럼 업권별 요율을 올리는 내용이었어요.","보험업권은 현행의 2.5~3배 수준 인상이라며 반발했고, 예금보험공사는 4차 회의에서 요율 산출 모형 일부를 고쳐 **연구용역안보다 낮은 요율**을 제시했어요. 보험업계는 받아들이는 분위기예요.","업권별 구체 요율은 아직 논의 중이에요. 예금보험공사는 11월부터 처음으로 협회뿐 아니라 **개별 금융사 의견**도 듣기로 했어요."],"why":"예금보험료는 보험사가 매년 내는 **고정 비용**이에요. 요율이 오르면 그만큼 이익이 줄고, 길게 보면 상품 사업비나 보험료에도 영향을 줄 수 있어요. 예금보험료는 부과 기준 금액에 요율을 곱해 정해지기 때문에, 같은 요율 인상이라도 **덩치가 큰 회사일수록 늘어나는 금액이 커요**. 이런 뉴스를 볼 땐 \"보호를 넓히는 비용은 누가, 얼마나 나눠 내는가\"를 생각해보세요.","chain":["예금보호한도가 1억 원으로 오름","예금보험기금 손실 우려가 커짐","연구용역안이 보험업권 요율을 크게 올림","보험업권이 산정 근거를 문제 삼아 반발","4차 회의에서 인상 폭을 낮춘 수정안이 나옴","최종 요율에 따라 보험사 고정 비용이 달라짐"],"role":{"q":"당신은 생명보험사 재무팀 신입이에요. 재무 담당 임원이 묻습니다. \"예금보험료율이 0.15%에서 0.40%로 오르면 우리 비용이 얼마나 늘지?\" 계산하는 방법을 설명해보세요.","model":"예금보험료는 부과 기준 금액에 요율을 곱해서 정해져요. $$\\text{예금보험료}=\\text{부과 기준 금액}\\times\\text{요율}$$ 설명을 위해 부과 기준 금액을 1조 원이라고 하면, 지금은 $$1\\text{조 원}\\times 0.15\\%=15\\text{억 원}$$이고 연구용역안대로면 $$1\\text{조 원}\\times 0.40\\%=40\\text{억 원}$$이라 **해마다 25억 원이 더 나가요**(설명을 위한 예시 숫자예요). 다만 4차 회의에서 인상 폭을 낮춘 수정안이 나왔으니, 최종 요율이 정해지면 그 숫자로 다시 계산하고 사업비 계획에 반영해야 한다고 보고해요."},"summary":"예금 보호 한도를 1억으로 올리면서 보험사가 내는 예금보험료를 2~3배 올리자는 안이 나왔는데, 반발이 커서 덜 올리는 수정안이 나왔어.","interview":{"q":"예금보험료율 인상 논의가 보험사 경영에 주는 영향을 설명해보세요.","guide":"결론부터: 예금보험료는 해마다 나가는 고정 비용이라, 요율이 오르면 이익과 사업비 여력이 줄어든다고 말해요.\n근거: 연구용역안은 생명보험 0.15%→0.40%, 손해보험 0.15%→0.50%였고, 4차 회의에서 인하 수정안이 나왔어요.\n관점: 계리·상품 관점에서는 고정 비용 증가가 길게 보면 상품의 사업비 가정에 반영될 수 있다는 점을 짚어요.\n마무리: 보호 확대의 취지와 업권별 위험에 맞는 공정한 부담이 함께 가야 한다고 마무리해요."},"quiz":[{"q":"예금보험료율 인상 논의가 시작된 배경은?","o":["예금보호한도가 1억 원으로 올라서","보험사 부실 사례가 크게 늘어서","보험사의 지급여력비율이 낮아져서"],"a":0,"e":"보호 한도가 5,000만 원에서 1억 원으로 오르며 기금 손실 대비 재원이 필요해졌어요."},{"q":"7월 연구용역안에서 요율 인상 폭이 가장 컸던 업권은?","o":["생명보험","손해보험","저축은행"],"a":1,"e":"손해보험은 0.15%에서 0.50%로, 현행 대비 인상 배수가 가장 컸어요."},{"q":"같은 요율 인상이라도 대형사의 부담이 더 큰 이유는?","o":["대형사는 요율이 더 높게 매겨져서","대형사만 인상된 요율을 적용받아서","기준 금액이 커서 요율을 곱한 값이 커지기 때문"],"a":2,"deep":true,"e":"예금보험료는 부과 기준 금액 × 요율이라, 기준 금액이 큰 회사일수록 늘어나는 금액이 커요."}],"terms":[{"t":"예금보험료율","d":"금융회사가 예금보험공사에 내는 예금보험료를 정하는 비율이에요."},{"t":"예금자보호한도","d":"금융회사가 문을 닫아도 예금보험공사가 1인당 돌려주는 최대 금액이에요. 2025년 9월부터 1억 원이에요."},{"t":"예금보험기금","d":"금융회사가 낸 예금보험료로 쌓아, 금융회사가 망했을 때 예금자에게 돈을 돌려주는 데 쓰는 기금이에요."},{"t":"사업비","d":"모집수수료 같은 계약체결비와 계약을 관리하는 유지비 등 보험을 운영하는 데 드는 비용이에요."}],"thread":{"id":"deposit-insurance","name":"예금보험료율 개편"},"jobs":["리스크관리","계리"],"figs":[{"type":"compare","title":"7월 연구용역안의 업권별 예금보험료율","left":"현행","right":"연구용역안","rows":[{"label":"은행","left":"0.08%","right":"0.13%"},{"label":"금융투자","left":"0.15%","right":"0.22%"},{"label":"생명보험","left":"0.15%","right":"0.40%"},{"label":"손해보험","left":"0.15%","right":"0.50%"},{"label":"저축은행","left":"0.40%","right":"0.54%"}],"note":"10월 30일 4차 회의에서 이보다 낮은 수정안이 나왔지만, 업권별 구체 요율은 아직 정해지지 않았어요.","look":"손해보험이 0.15%에서 0.50%로 가장 많이 오르는 안이었어요."}],"sources":[{"name":"헤럴드경제","url":"https://biz.heraldcorp.com/article/10924317"}],"brief":{"what":"예금보험공사가 10월 30일 4차 회의에서 보험업권 예금보험료율 인상 폭을 낮춘 수정안을 내놨어요.","why":"예금보호한도가 1억 원으로 오르며 기금 손실에 대비할 재원이 필요해졌고, 7월 연구용역안은 보험업권에 **현행의 2.5~3배** 요율을 제시해 업계가 반발했어요.","so":"예금보험료는 해마다 나가는 고정 비용이라 요율이 오르면 이익이 줄고, 길게 보면 사업비 가정에도 영향을 줄 수 있어요."},"pre":["예금보험료율","예금자보호한도"]},{"id":"2026-11-04-16","date":"2026-11-04","tag":"판매채널","title":"무료 케이크 수업에 갔다가 종신보험 가입? 공짜 강연 보험 영업 주의보","predict":{"q":"육아박람회에서 설계사가 \"모든 보장이 100세까지 유지된다\"고 설명했어요. 민원으로 드러난 실제 주요 특약의 만기는?","options":["정말 100세까지","60세 또는 90세","30세 또는 80세"],"answer":2,"reveal":"주요 특약의 만기는 **30세 또는 80세**였어요. 금융당국은 무료 강연이나 박람회에서 보험을 권유받으면 **가입 목적, 보장기간, 해지환급금**을 꼭 확인하라고 당부했어요."},"comic":{"title":"공짜 수업의 끝에는","panels":[{"caption":"무료 케이크 만들기 수업","bg":"meeting","chars":[{"who":"sweetpotato","mood":"happy","pose":"cheer","fx":"heart","say":"공짜로 케이크를 만든대!"}]},{"caption":"수업이 끝나자","bg":"meeting","chars":[{"who":"planner","mood":"happy","pose":"point","say":"목돈 마련엔 이 보험이 딱이에요"},{"who":"sweetpotato","mood":"thinking","pose":"think","fx":"question"}]},{"caption":"집에 와서 약관을 보니","bg":"home","sign":"중도 해지 시 원금 손실","chars":[{"who":"sweetpotato","mood":"surprised","pose":"phone","fx":"exclaim","say":"이게 종신보험이었어?"}]},{"caption":"망고 계리사의 정리","bg":"office","chars":[{"who":"mango","mood":"thinking","pose":"doc","say":"종신보험은 사망을 보장해요"},{"who":"sweetpotato","mood":"happy","pose":"stand","fx":"idea","say":"가입 목적부터 확인할게요"}]}]},"points":["금융당국에 따르면 무료 재테크 강연, 육아박람회 같은 곳의 보험 영업 민원이 꾸준히 들어오고 있어요. 무료 케이크 수업에서 **사전 안내 없이 보험을 권유받고**, 중도 해지 때 원금 손실이 크다는 설명을 못 들었다는 사례도 있었어요.","**종신보험은 사망을 보장하는 상품이지 저축성보험이 아니에요.** 목돈 마련용으로 권유받았다면 의심해야 하고, 중도 해지하면 낸 보험료보다 적게 돌려받을 수 있어요.","기존 보험을 해지하고 갈아탈 때는 보장 범위, 보험료, 특약별 만기를 비교해야 해요. 고지의무를 사실과 다르게 알리면 보험금 지급이 거절될 수 있고, 해피콜에서도 실제 들은 대로 답해야 해요."],"why":"상품이 아무리 잘 설계돼도 **판매 현장에서 다르게 설명되면** 소비자 피해와 민원, 해지로 돌아와요. 계리 관점에서는 잘못 알고 가입한 계약일수록 일찍 해지될 가능성이 높아 해지율 가정이 흔들리고, 상품개발 관점에서는 특약별 만기와 해약환급금이 한눈에 보이도록 설명 자료를 만드는 것도 설계의 일부예요. 이런 뉴스를 볼 땐 \"이 상품이 판매 현장에서 어떤 말로 팔리고 있을까\"를 상상해보세요.","chain":["무료 강연·박람회로 사람을 모음","현장에서 보험 가입을 권유함","종신보험을 저축처럼, 특약 만기를 길게 설명함","소비자가 잘못 알고 가입함","중도 해지 손실과 민원이 생김","당국이 주의를 당부하고 판매 책임이 강조됨"],"role":{"q":"당신은 생명보험사 상품개발팀 신입이에요. 팀장님이 말합니다. \"박람회 영업 민원이 우리 종신보험에도 들어왔대. 상품 쪽에서 할 수 있는 게 있을까?\" 개선안을 말해보세요.","model":"먼저 상품설명서 첫 장에 **'이 상품은 사망을 보장하는 보험이에요'**라는 성격과 특약별 만기를 표로 분명히 보여주는 걸 제안해요. 100세까지 보장되는 것과 30세·80세에 끝나는 특약이 섞여 있으면 소비자가 헷갈리기 쉬워서예요. 해약환급금 예시표도 연도별로 눈에 띄게 넣어, 일찍 해지하면 낸 보험료보다 적게 받는다는 걸 숫자로 보여줘야 해요. 또 해피콜 질문에 '저축 목적으로 가입하셨나요?'처럼 오해를 걸러낼 문항을 넣으면, 잘못 판매된 계약을 일찍 찾아 해지율 가정이 흔들리는 것도 막을 수 있어요."},"summary":"공짜 강연이나 박람회에서 보험 권유받으면, 그게 저축인지 사망보험인지, 보장이 언제 끝나는지, 중간에 깨면 얼마 받는지 꼭 확인해.","interview":{"q":"불완전판매가 보험사의 계리·상품 측면에 어떤 영향을 주는지 사례로 설명해보세요.","guide":"결론부터: 불완전판매는 민원뿐 아니라 이른 해지로 이어져 계리가정과 상품 수익성을 흔든다고 말해요.\n근거: 금융당국은 무료 강연·박람회 영업 민원이 꾸준하다고 했고, 종신보험을 저축처럼 권유하거나 특약 만기를 100세로 잘못 안내한 사례가 있었어요.\n관점: 상품개발 관점에서 특약별 만기와 해약환급금이 한눈에 보이는 설명 자료와 해피콜 문항 개선을 제안해요.\n마무리: 좋은 상품은 제대로 팔릴 때 완성된다고 마무리해요."},"quiz":[{"q":"저축이나 목돈 마련을 위해 종신보험을 권유받았다면 왜 주의해야 할까?","o":["저축성보험이지만 첫해에는 이자가 붙지 않아 손해를 볼 수 있어서","사망을 보장하는 상품이라 중도 해지하면 낸 보험료보다 적게 받을 수 있어서","사망보장 없이 해지할 때만 돈이 나오는 상품이라 이득이 없어서"],"a":1,"e":"종신보험은 저축성보험이 아니라 사망을 보장하는 상품이고, 중도 해지하면 낸 보험료보다 적게 받을 수 있어요."},{"q":"가입 뒤 보험사의 해피콜에서 해야 할 일은?","o":["실제로 설명받은 내용대로 답하기","설계사가 알려준 모범 답변대로 말하기","헷갈리는 질문은 모두 '네'로 답하기"],"a":0,"e":"알려준 답을 따라 하거나 헷갈려도 '네'라고 하면 나중에 분쟁에서 불리한 증거가 될 수 있어요."},{"q":"잘못 알고 가입한 계약이 많아지면 계리가정에서 가장 먼저 흔들릴 수 있는 것은?","o":["사망률","사업비율","해지율"],"a":2,"deep":true,"e":"오해로 가입한 계약은 일찍 해지될 가능성이 커서 해지율 가정과 실제가 벌어질 수 있어요."}],"terms":[{"t":"종신보험","d":"평생 보장하고, 언제 사망하든 정해진 사망보험금을 유족에게 주는 생명보험이에요."},{"t":"해약환급금","d":"계약자가 보험을 중간에 해지할 때 돌려받는 돈이에요."},{"t":"해피콜","d":"가입 뒤 보험사가 계약자에게 연락해 설명을 제대로 들었는지 확인하는 절차예요."},{"t":"특약 만기","d":"주계약에 덧붙인 특약의 보장이 끝나는 시점이에요. 주계약과 다를 수 있어요."},{"t":"고지의무","d":"보험에 들 때 건강 상태 같은 중요한 사실을 보험사에 사실대로 알려야 하는 의무예요."}],"thread":{"id":"sales-channel","name":"판매채널과 수수료"},"jobs":["영업·채널","상품개발"],"figs":[{"type":"compare","title":"현장에서 들은 말과 실제 계약","left":"현장 설명","right":"실제 계약","rows":[{"label":"상품 성격","left":"목돈 마련에 좋은 보험","right":"사망을 보장하는 종신보험"},{"label":"보장기간","left":"모든 보장이 100세까지","right":"주요 특약은 30세 또는 80세 만기"},{"label":"중도 해지","left":"설명 없음","right":"낸 보험료보다 적게 받을 수 있음"}],"note":"금융당국에 들어온 민원 사례를 정리한 표예요.","look":"현장에서 들은 말과 실제 계약이 성격, 보장기간, 중도 해지에서 달라요."}],"sources":[{"name":"한국경제","url":"https://www.hankyung.com/article/2026110320641"}],"brief":{"what":"무료 케이크 수업이나 육아박람회 같은 공짜 강연에서 보험을 권유받았다는 민원이 꾸준히 들어와 금융당국이 주의를 당부했어요.","why":"현장에서 종신보험을 저축처럼 소개하고 특약 만기도 길게 설명해, 소비자가 잘못 알고 가입하기 쉽기 때문이에요.","so":"소비자는 **가입 목적, 보장기간, 해지환급금**을 꼭 확인해야 하고, 보험사는 잘못 알고 가입한 계약이 일찍 해지돼 해지율 가정이 흔들리는 일을 막아야 해요."},"pre":["종신보험","특약 만기"]},{"id":"2026-11-04-17","date":"2026-11-04","tag":"상품개발","title":"700종신이 사라진 자리, 건강종신과 인출형 종신의 2파전","predict":{"q":"판매가 멈추기 전, 신한라이프에서 700종신이 차지한 판매 비중은 얼마였을까요?","options":["약 15%","약 8%","약 25%"],"answer":0,"reveal":"**약 15%**였어요. 금감원이 9월 21일 개선방안을 전달한 뒤 신규 판매가 사실상 멈췄고, 생보사들은 **건강종신과 인출형 종신**으로 빈자리를 메우려 하고 있어요. 그래도 판매량은 아직 700종신에 못 미친다는 평가예요."},"comic":{"title":"빈자리를 채워라","panels":[{"caption":"9월 21일 이후","bg":"meeting","board":"down","sign":"700종신 판매 중단","chars":[{"who":"insurer","mood":"worried","pose":"worry","say":"주력 상품이 빠졌어요…"}]},{"caption":"새 카드 두 장","bg":"office","chars":[{"who":"insurer","mood":"thinking","pose":"doc","say":"건강종신? 인출형 종신?"},{"who":"planner","mood":"thinking","pose":"phone","say":"아직 예전만큼 안 팔려요"}]},{"caption":"당국이 본 문제","bg":"focus","sign":"7년 뒤 환급률 100%","chars":[{"who":"regulator","mood":"thinking","pose":"point","say":"저축으로 오해할 수 있어요"}]},{"caption":"망고 계리사의 정리","bg":"office","chars":[{"who":"mango","mood":"happy","pose":"point","fx":"idea","say":"남은 계약의 해지율도 다시 봐요"}]}]},"numbers":[{"label":"700종신 판매 사실상 중단","value":"9월 21일","note":"금감원 개선방안 전달"},{"label":"신한라이프 700종신 비중","value":"약 15%","note":"판매 중단 전"},{"label":"일부 건강종신 10년 환급률","value":"113% 안팎","note":"112~113% 수준 상품도"},{"label":"KB라이프 연말 보험계약마진 예상","value":"3조 5,000억 원","note":"전년 말보다 약 8% 증가"}],"points":["700종신은 가입 7년 뒤 해약환급금이 낸 보험료의 100% 수준이 되는 종신보험이에요. 금감원은 **저축성 보험으로 오인될 수 있고, 환급 시점에 해지가 몰리면 보험사 지급 부담이 커질 수 있다**고 봤어요.","대체 상품은 두 갈래예요. **건강종신**은 암 같은 중대질병 진단 때 보험금을 미리 주고 사망보장도 묶은 상품이고, **인출형 종신**은 납입보험료의 최대 100%까지 생전에 꺼내 쓰면서 사망보장을 유지해요. 현장에서는 건강종신이 더 활발하다는 평가예요.","ABL생명은 2일 생활자금을 인출할 수 있는 종신보험을, 동양생명은 3일 질환 진단 때 남은 보험료를 면제하는 건강종신을 내놨어요. KB라이프와 신한라이프는 연말 결산에서 **기존 계약의 해지율 가정**을 다시 조정할 계획이에요."],"why":"상품 하나가 빠졌는데 업계가 흔들리는 건, 그 상품이 **신계약과 보험계약마진을 떠받치고 있었기 때문**이에요. 계리 관점에서 더 중요한 숙제는 이미 팔린 계약이에요. 7년 시점 환급률이 100%에 닿으면 해지가 몰릴 수 있어서, 해지율 가정이 실제와 다르면 보유 보험계약마진을 연말에 고쳐야 해요. 상품개발 관점에서는 높은 환급률과 충분한 판매수수료를 함께 지키기 어려워진 지금, **무엇을 소비자 가치로 내세울지**가 경쟁의 핵심이 돼요.","chain":["7년 뒤 환급률 100% 수준의 700종신이 많이 팔림","금감원이 저축성 오인과 해지 집중을 우려","9월 21일 이후 신규 판매가 사실상 중단","신계약과 보험계약마진에 공백이 생김","건강종신·인출형 종신으로 대체 경쟁","연말 결산에서 기존 계약 해지율 가정을 다시 조정"],"role":{"q":"당신은 신한라이프 계리팀 신입이에요. 팀장님이 묻습니다. \"700종신이 판매의 15%였는데, 연말 결산에서 무엇을 다시 봐야 할까?\" 생각을 정리해보세요.","model":"가장 먼저 볼 것은 **이미 팔린 700종신의 해지율 가정**이에요. 7년 시점에 해약환급금이 낸 보험료 수준이 되면, 그때 해지하려는 계약자가 몰릴 수 있어요. 지금 가정한 해지율이 실제보다 낮으면 앞으로 나갈 해약환급금이 더 커지고, 그만큼 보유 보험계약마진이 줄어들어요. 그래서 실제 해지 흐름과 가정의 차이를 확인하고 연말에 반영해야 해요. 회사는 올해 늘어난 보험계약마진으로 영향을 흡수할 수 있다고 봤지만, **대체 상품의 신계약이 예전만 못하면** 내년 보험계약마진 증가 속도는 느려질 수 있다는 점도 함께 보고해요."},"summary":"7년만 지나면 낸 돈 다 돌려주던 종신보험이 막히자, 보험사들이 암 걸리면 미리 주는 종신보험이랑 살면서 꺼내 쓰는 종신보험으로 빈자리를 메우는 중이야.","interview":{"q":"700종신 판매 중단이 생명보험사에 남긴 과제를 계리 관점에서 설명해보세요.","guide":"결론부터: 신계약 공백과 기존 계약의 해지율 가정 재점검, 두 가지 과제가 남았다고 말해요.\n근거: 금감원이 9월 21일 개선방안을 전달한 뒤 판매가 멈췄고, 신한라이프는 판매 비중이 약 15%였어요. KB라이프·신한라이프는 연말 해지율 가정 조정을 예고했어요.\n관점: 해지율이 가정보다 높으면 보유 보험계약마진이 줄어들 수 있고, 대체 상품은 환급률·건강보장·인출 기능 중 무엇으로 차별화할지가 관건이라고 덧붙여요.\n마무리: 판매 실적보다 오래 유지되는 계약을 만드는 상품 설계가 중요하다고 마무리해요."},"quiz":[{"q":"금감원이 700종신에서 걱정한 점으로 알맞은 것은?","o":["환급률이 낮아 중도 해지 때 손해를 볼 수 있다","질병 진단 때 보험금을 미리 주는 기능이 없다","저축성 보험으로 오인될 수 있고 해지가 몰릴 수 있다"],"a":2,"e":"7년 뒤 환급률 100% 수준이라 저축처럼 보이고, 그 시점에 해지가 몰리면 지급 부담이 커질 수 있어요."},{"q":"건강종신과 인출형 종신의 차이로 알맞은 것은?","o":["건강종신은 생전에 돈을 꺼내 쓰고, 인출형은 진단 때 보험금을 미리 준다","건강종신은 진단 때 보험금을 미리 주고, 인출형은 생전에 돈을 꺼내 쓴다","인출형은 사망보장을 없애는 대신 돈을 꺼내 쓸 수 있게 한다"],"a":1,"e":"건강종신은 중대질병 선지급, 인출형 종신은 납입보험료 범위에서 생전 인출이 핵심이에요."},{"q":"해지율 가정이 실제보다 낮았다면 연말에 보유 보험계약마진은 어떻게 될 가능성이 클까?","o":["늘어난다. 보험료를 가정보다 오래 받을 수 있기 때문","변하지 않는다. 해지는 당해 보험손익에만 반영되기 때문","줄어든다. 가정보다 해약환급금이 더 많이 나가기 때문"],"a":2,"deep":true,"e":"가정보다 해지가 많으면 나갈 해약환급금이 커져 앞으로의 이익인 보험계약마진이 줄어들 수 있어요."}],"terms":[{"t":"700종신","d":"가입 7년 뒤 해약환급금이 낸 보험료의 100% 수준이 되도록 설계한 종신보험을 업계에서 부르는 말이에요."},{"t":"건강종신","d":"암 같은 중대질병을 진단받으면 보험금을 미리 주고, 사망보장도 함께 유지하는 종신보험이에요."},{"t":"인출형 종신보험","d":"살아 있는 동안 납입보험료 범위에서 돈을 꺼내 쓰면서 사망보장을 유지하는 종신보험이에요."},{"t":"해지율","d":"보험계약이 일정 기간 안에 중도 해지되는 비율이에요. 보험료와 보험부채 계산의 핵심 가정이에요."},{"t":"보험계약마진","d":"보험계약에서 앞으로 나눠서 이익으로 인식할, 아직 실현되지 않은 이익이에요."}],"thread":{"id":"product-competition","name":"보험상품 개발 경쟁"},"jobs":["상품개발","계리","영업·채널"],"companies":["신한라이프","KB라이프","동양생명","ABL생명"],"figs":[{"type":"compare","title":"700종신 빈자리를 노리는 두 상품","left":"건강종신","right":"인출형 종신","rows":[{"label":"핵심 기능","left":"중대질병 진단 때 보험금 선지급","right":"납입보험료 최대 100%까지 생전 인출"},{"label":"사망보장","left":"유지하거나 일부 회복","right":"인출해도 유지"},{"label":"기사 속 비교 회사","left":"6곳","right":"6곳"},{"label":"현장 분위기","left":"상대적으로 더 활발","right":"콘셉트가 분명해 팔기 쉬움"}],"note":"두 상품의 설계사 수수료 수준은 대체로 비슷해, 경쟁은 환급률·건강보장·인출 기능에서 갈릴 것으로 보여요.","look":"건강종신은 진단 때 선지급, 인출형은 생전 인출이 핵심이에요."}],"sources":[{"name":"파이낸셜투데이","url":"https://www.ftoday.co.kr/news/articleView.html?idxno=368823"},{"name":"보험저널","url":"https://www.insjournal.co.kr/news/articleView.html?idxno=33782"}],"brief":{"what":"금감원 개선방안 전달 뒤 700종신 신규 판매가 사실상 멈추자, 생보사들이 건강종신과 인출형 종신으로 빈자리를 메우고 있어요.","why":"7년 뒤 환급률이 100% 수준인 700종신이 **저축성 보험으로 오인되고 해지가 몰릴 수 있다**고 금감원이 봤기 때문이에요.","so":"신계약 공백을 대체 상품이 채워야 하고, 이미 팔린 계약은 연말 결산에서 해지율 가정을 다시 조정해 보험계약마진에 미칠 영향을 봐야 해요."},"pre":["700종신","해지율"]}]);
